// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/// @notice Everything a creator chooses at launch. Immutable afterwards: there
///         is no setter for any field, and the only two owner functions on the
///         token are {reduceTaxes} (down-only) and {renounce}.
/// @dev Written to storage in `initialize()`, never `immutable` - these are
///      EIP-1167 clones, and an `immutable` lives in the IMPLEMENTATION's code,
///      so every clone would read the implementation's value. That mistake is
///      silent: it compiles, deploys, and gives every token the same tax rate.
struct TaxConfig {
    /// @dev 0..1000 (max 10%). Skimmed on transfers OUT of the main pool.
    uint16 buyTaxBps;
    /// @dev 0..1000 (max 10%). Charged as a surcharge on the seller's REMAINING
    ///      balance - never deducted from what the pool receives. See ArgusErrors.
    uint16 sellTaxBps;
    /// @dev creatorBps + burnBps + dividendBps MUST equal 10000. They split the
    ///      tax inflow AFTER the protocol fee has been skimmed off the top.
    uint16 creatorBps;
    uint16 burnBps;
    uint16 dividendBps;
    /// @dev Required non-zero when creatorBps > 0.
    address creatorWallet;
    /// @dev Seconds. 0 means permanent; otherwise all taxes read as 0 once
    ///      `launchedAt + taxDuration` has passed. Expiry can never be undone
    ///      and can never be re-armed.
    uint32 taxDuration;
    /// @dev Dust filter: holders below this earn no dividends and cost no gas.
    ///      In TOKEN units (18dp), not native.
    uint96 minimumShareBalance;
}

library ArgusConstants {
    uint16 internal constant BPS = 10_000;

    /// @dev Hard ceiling on either tax, enforced at initialize AND in
    ///      reduceTaxes. 10%.
    uint16 internal constant MAX_TAX_BPS = 1_000;

    /// @dev Paid to whoever calls `swapBack()`, out of the proceeds. Exists so
    ///      swap-back still happens when our own trigger bot is down - the
    ///      whole trust model is "permissionless core, bot as convenience".
    uint16 internal constant SWAPBACK_BOUNTY_BPS = 50; // 0.5%

    /// @dev A swap-back reverts if it returns less than this share of the
    ///      output implied by the pool's pre-swap price.
    ///
    ///      This is a FILL-QUALITY check, and calling it sandwich protection -
    ///      as this comment used to - describes a protection that does not
    ///      exist. The benchmark is derived from `sqrtPriceX96` read in the same
    ///      call as the swap, so a sandwicher's front-run leg has ALREADY moved
    ///      the price by the time the quote is taken, and the floor is computed
    ///      against the moved price. What it does catch is a fill far worse than
    ///      the pool's own posted state implied: thin depth past the tick, or a
    ///      pool poisoned between blocks. That is worth having; it is just not
    ///      the thing the old name promised.
    uint16 internal constant SLIPPAGE_FLOOR_BPS = 8_500; // 85%

    /// @dev Ceiling on how far ONE swap may push the pool price, as a fraction of
    ///      the pool's in-range virtual reserve of whichever token is going in.
    ///
    ///      It is derived, not guessed. For an exact-input swap of size `x` into a
    ///      constant-liquidity range, realised output is exactly
    ///      `spotOutput / (1 + d)`, where `d = x·sqrtP/L` for token0-in and
    ///      `d = x/(L·sqrtP)` for token1-in - and both reduce to
    ///      `d = x / the pool's virtual reserve of the input token`. On the worst
    ///      canonical fee tier (1%) the realised fraction of spot is
    ///      `0.99 / (1 + d)`, so {SLIPPAGE_FLOOR_BPS} is only reached at
    ///      d ~= 0.165. 5% leaves roughly 3x margin for liquidity thinning across
    ///      tick boundaries.
    ///
    ///      Shared, and deliberately so. Both swap paths against the pool size
    ///      themselves with this: {ArgusTaxToken-swapBack} selling the tax
    ///      accumulator, and {ArgusTaxProcessor-executeBurn} spending the burn
    ///      bucket the other way. They are the same guard against the same pool,
    ///      and the two grew the same deadlock independently - an uncapped swap
    ///      whose size ratchets past its own slippage floor and then reverts
    ///      forever. Keeping one constant is what stops them drifting apart again.
    ///
    ///      CAVEAT, now covering two call sites: the derivation assumes a fee tier
    ///      of AT MOST 1%. Neither caller reads `pool.fee()`. Arc's canonical
    ///      tiers top out there, so the 3x margin holds today; a non-canonical
    ///      tier would eat into it silently.
    uint16 internal constant MAX_PRICE_IMPACT_BPS = 500; // 5%

    /// @dev Parts-per-million. Retained for callers that denominate in supply;
    ///      the swap-back trigger no longer does. See below.
    uint32 internal constant PPM = 1_000_000;

    /// @notice Swap back once the accumulated tax is worth this much, in the 6dp
    ///         USDC view. $10.
    ///
    /// @dev Denominated in QUOTE VALUE, deliberately, and this replaced an
    ///      earlier supply-denominated rule (400ppm of supply) that was wrong on
    ///      this chain. A supply-denominated trigger has a dollar value that
    ///      scales with price, so it withheld more and more tax as a token
    ///      succeeded: on a 1B supply it meant $1 at a $2.5k FDV but $20,000 at
    ///      $50M. The thing it was amortising - a full swapBack + dispatch cycle
    ///      at 25 gwei - costs about $0.0112 on Arc. Batching thousands of
    ///      dollars to save one cent is not a trade, and it has a real cost: one
    ///      large swap-back is a single visible dump, where the same volume in
    ///      small slices is absorbed into normal flow and partly recovers between
    ///      sells.
    ///
    ///      $10 is ~900x the gas cost, so swap-back stays efficient at every
    ///      FDV, and it makes the 0.5% caller bounty $0.05 against $0.0063 of gas
    ///      for `swapBack()` alone - third-party keeping is profitable at any
    ///      size, which under the old rule it was not at low FDV.
    /// TWO NUMBERS, TWO QUESTIONS. Worth stating together, because they look
    /// parallel and are not, and conflating them is what the removed EMA
    /// controller did.
    ///
    ///   MIN_SWAPBACK_VALUE_USDC6  answers "is this worth selling yet?"
    ///                                and is therefore in DOLLARS
    ///   MAX_PRICE_IMPACT_BPS         answers "how much can the pool absorb?"
    ///                                and is therefore a fraction of RESERVE
    ///
    /// One quantity cannot track two independent things without conflating
    /// them. The old threshold was supply-denominated and fed a controller whose
    /// input was output-per-token, which is dominated by price level rather than
    /// by depth: a token whose price doubled produced "better output" and the
    /// controller read that as a strong market. It was integrating price drift
    /// and reporting it as market health.
    ///
    /// A dollar trigger absorbs that drift for free. In a weak market the same
    /// accrual is worth less, so it takes longer to reach the threshold and
    /// sells become rarer on their own, with no feedback loop and no lag.
    uint256 internal constant MIN_SWAPBACK_VALUE_USDC6 = 10e6;

    /// @dev Sanity floor, in TOKENS, under the value trigger above: a pool that
    ///      is empty, unpriceable, or manipulated to an absurd price must not be
    ///      able to satisfy a $10 valuation with dust. Expressed as a fraction of
    ///      supply so it scales with the launch rather than assuming 1B.
    ///
    ///      Set so low it cannot bind under any honest valuation, and the claim
    ///      is falsifiable rather than vague: the floor binds only once $10 buys
    ///      fewer than `totalSupply / 1e9` tokens, i.e. above an FDV of
    ///      `$10 * 1e9` = $10 BILLION. On a 1B-token supply the floor is 1 token.
    uint256 internal constant MIN_SWAPBACK_SUPPLY_DIVISOR = 1e9;

    /// @dev OZ's ERC20 reverts on transfers to address(0), so burns go here.
    address internal constant DEAD = 0x000000000000000000000000000000000000dEaD;

    /// @dev Gas forwarded to a holder on a dividend payout. Enough for an EOA
    ///      and a thin receiver, not enough for a contract to grief the batch.
    uint256 internal constant PAYOUT_GAS_STIPEND = 30_000;
}

library ArgusErrors {
    error AlreadyInitialized();
    error NotInitialized();

    error TaxTooHigh(); // > MAX_TAX_BPS at initialize or reduceTaxes
    error TaxesNotDownOnly(); // reduceTaxes tried to raise one
    error AllocationMustSumTo10000();
    error ZeroTaxNotAllowed(); // buyTaxBps + sellTaxBps == 0: use a plain token
    error CreatorWalletRequired(); // creatorBps > 0 with a zero wallet

    error OnlyToken();
    error OnlyOwner();
    error OnlyPortal();

    error PoolAlreadySet();
    error PoolNotSet();
    error PreGraduationPoolTransfer(); // §1 Phase A: no pool may be seeded early

    error BelowSwapBackThreshold();
    error SlippageFloorBreached(); // proceeds under SLIPPAGE_FLOOR_BPS of expected
    error NothingToSwapBack();
    error UnexpectedCallback(); // swap callback from a pool we did not call

    // NothingToDispatch was removed rather than left unraised. A declared error
    // is documentation: a reader seeing it here reasonably concludes dispatch
    // reverts on empty buckets, which is the exact wrong inference and the one
    // that cost three agents a round of work. dispatch() is a no-op when there
    // is nothing to do.
    error ZeroAddress();
}

src/ArgusV4LaunchConfig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/// @notice How a launch pays its holder rewards. ONE per-launch flag, three
///         values, one code path in {ArgusV4RewardTracker}.
///
/// @dev `NONE` is the absence of the feature rather than a fourth behaviour: the
///      token clones no tracker and {ArgusV4LaunchToken-_update} does no extra
///      work at all. `QUOTE` and `IN_KIND` differ by ONE stored address - which
///      ERC-20 the tracker pays out - and by nothing else. See the note on
///      {ArgusV4RewardTracker-payoutAsset}.
enum RewardMode {
    NONE,
    QUOTE,
    IN_KIND
}

/// @notice Everything a creator chooses about rewards for one v4 launch.
///
/// @dev `minimumShareBalance` is in TOKEN units (18dp) and is bounded at USE
///      time, not here - see {ArgusV4RewardTracker-_effectiveMinShare}. It is
///      carried in this struct rather than derived because it is the one reward
///      parameter a creator legitimately wants to set per launch.
struct RewardConfig {
    RewardMode mode;
    uint96 minimumShareBalance;
}

/// @title ArgusV4LaunchConfig
/// @notice The pre-launch config a creator writes for their own next v4 launch.
///
/// @dev 🔴 WHY THIS CONTRACT EXISTS AT ALL, because a reviewer's first reaction
///      is that it should not.
///
///      {IArgusV4LaunchToken} is FROZEN. Its eight arguments are
///      `(name, symbol, logoURI, totalSupply, supplyRecipient, owner, portal,
///      extraExempt)` and there is no slot for launch config of any kind.
///      `ArgusV4Portal` is merged and audited and this repository is not allowed
///      to change it, so a per-launch reward flag CANNOT arrive through the
///      seam. Three ways were considered and two rejected:
///
///        1. A POST-LAUNCH OWNER SETTER. Rejected. The Portal passes
///           `owner = msg.sender`, so the creator really could set the mode in a
///           second transaction - but the token is tradeable the instant
///           {ArgusV4Portal-launch} returns, so between the two transactions the
///           launch runs at whatever the default is. That window is small and
///           real, and it is avoidable, which is what makes taking it a choice
///           rather than a constraint.
///        2. ONE TOKEN IMPLEMENTATION PER MODE. Rejected. `tokenImpl` is a
///           Portal constructor immutable, so a second mode means a SECOND
///           PORTAL - two launch indexes, two `allTokens` arrays, two addresses
///           for a front end and an indexer to know about, to express one
///           boolean.
///        3. THIS. The creator writes their config BEFORE the launch, keyed by
///           their own address; the token reads it during `initialize` and
///           copies it into its own storage. The config is fixed before the
///           token exists, so there is no window at all.
///
///      THE KEY IS `msg.sender` HERE AND `owner` THERE, AND THEY ARE THE SAME
///      ADDRESS. `ArgusV4Portal._deployParts` passes its own `msg.sender` as
///      both `owner` and the locker's `creator` (src/ArgusV4Portal.sol:641), so
///      a config written by address A can only ever be read by a launch A
///      itself signed. There is no path by which one creator's config reaches
///      another creator's launch, and that is a property of the key rather than
///      of a check.
///
///      NO OWNER, NO PAUSE, NO UPGRADE, and no per-launch nonce. A config
///      PERSISTS: a creator who launches twice and changes nothing gets the same
///      reward mode both times. That is deliberate - the alternative is a
///      single-use config that silently reverts to defaults on a second launch,
///      which is a worse surprise than a remembered choice.
///
///      A creator who never calls {setConfig} launches with `RewardMode.NONE`,
///      because the zero value of an unwritten mapping IS the zero member of the
///      enum. That is the default by construction rather than by a branch, and
///      `test_unsetCreatorGetsNone` pins it so a future member added at position
///      zero cannot silently change what an absent config means.
contract ArgusV4LaunchConfig {
    /// @notice The config that will be read by `creator`'s next launch.
    mapping(address creator => RewardConfig) public configOf;

    event ConfigSet(address indexed creator, RewardMode mode, uint96 minimumShareBalance);

    /// @notice Write the caller's own launch config. Idempotent, overwritable,
    ///         and callable at any time.
    function setConfig(RewardConfig calldata cfg) external {
        configOf[msg.sender] = cfg;
        emit ConfigSet(msg.sender, cfg.mode, cfg.minimumShareBalance);
    }

    /// @notice Read a creator's config. Returns the `NONE` zero value when the
    ///         creator has never written one.
    /// @dev A getter beside the public mapping because the token reads it through
    ///      an interface and a struct-returning mapping getter decodes as a
    ///      tuple, which is fragile to reorder. This one is explicit.
    function configFor(address creator) external view returns (RewardMode mode, uint96 minimumShareBalance) {
        RewardConfig memory c = configOf[creator];
        return (c.mode, c.minimumShareBalance);
    }
}

src/ArgusV4RewardTracker6.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {ArgusConstants, ArgusErrors} from "./types/ArgusTypes.sol";
import {ArgusUnits} from "./libraries/ArgusUnits.sol";
import {RewardMode} from "./ArgusV4LaunchConfig.sol";

/// @notice The metadata read this tracker makes on its payout asset, once.
/// @dev Declared here rather than imported from OZ's `IERC20Metadata` because
///      only one function of it is called and a token whose `decimals()` reverts
///      must be refused rather than defaulted - see {ArgusV4RewardTracker6-initialize}.
interface IERC20Decimals {
    function decimals() external view returns (uint8);
}

/// @title ArgusV4RewardTracker6
/// @notice Pro-rata holder rewards for ONE `ArgusV4LaunchToken6`, in either the
///         launch's own quote asset or the token itself. Portal #6's tracker.
///
/// @dev {ArgusV4RewardTracker} WITH ONE CHANGE, AND THE CHANGE IS {receive}.
///      That contract is Portal #5's deployed `rewardTrackerImpl` and is not
///      edited; this is a copy (SPEC_PORTAL6.md §2.5). Everything below is its
///      text, carried over, except where a sentence named the paired token or
///      assumed the quote is Arc USDC.
///
///      WHY A COPY WAS NEEDED AT ALL. The original's {receive} accepted native
///      whenever `mode == RewardMode.QUOTE`, which read QUOTE as "native" - true
///      while every launch was paired against `0x3600`, whose ERC-20 view IS the
///      native balance. Portal #6 admits other quote assets per launch, and
///      {ArgusV4LaunchToken6} hands a QUOTE tracker that launch's own quote.
///      Under such a quote, native sent here raises a balance {syncDeposit} never
///      reads and {_transfer} never moves, on a contract with no owner and no
///      sweep. So the guard now asks the question it always meant: is the payout
///      asset the one the native balance mirrors? The five departures below are
///      unchanged, and this is NOT a sixth: they are departures from the v3
///      {ArgusDividendTracker}, and this is a change from the v4 original.
///
///      THE TESTS AND TOOLS NAMED BELOW RUN AGAINST THE ORIGINAL. Every `test_*`,
///      `AuditP4` case and `ordering-census.mjs` rule cited in this file was
///      written against {ArgusV4RewardTracker} and still executes against it. They
///      describe this code because it is that code outside {receive}; they do not
///      execute it. What executes against THIS contract is
///      `test/unit/ArgusV4LaunchToken6.t.sol`.
///
///      PORTED FROM {ArgusDividendTracker}, WHICH IS LIVE AND AUDITED, WITH FIVE
///      DELIBERATE DEPARTURES. Each is a place the v3 contract cannot be copied
///      verbatim without being wrong on a v4 venue, and each is named so a
///      reviewer can check the list against the code instead of diffing 900
///      lines.
///
///      THE COUNT WAS FOUR AND THE CODE ALWAYS HAD FIVE. P-5 is declared forty
///      lines below the block that holds P-1..P-4, on {PAYOUT_GAS_STIPEND}'s
///      absence, and cross-referenced three more times. A reviewer who trusted
///      the number stopped at P-4 and never reached the departure that DELETED
///      A GUARD. Pinned by `test_R1_theDeparturesAreFiveAndTheHeaderSaysFive`,
///      which counts `P-N` declarations in this file and fails if the header's
///      number and the code's disagree - in either direction.
///
///      ------------------------------------------------------------------
///      P-1  THE PAYOUT IS AN ERC-20 TRANSFER, NEVER A NATIVE SEND, AND THAT
///           IS WHAT MAKES ONE FLAG ENOUGH.
///      ------------------------------------------------------------------
///      {ArgusDividendTracker} pays with `to.call{value:}` at every one of its
///      exits, so its payout asset is native and cannot be anything else - which
///      is why an in-kind mode is not expressible in it at all rather than
///      merely absent. Here {payoutAsset} is ONE STORED ADDRESS and every exit
///      goes through {_pay}. `RewardMode.QUOTE` stores the quote asset;
///      `RewardMode.IN_KIND` stores the launched token. Nothing else in this
///      contract branches on the mode, which is what "one flag, not two code
///      paths" means concretely.
///
///      When the quote is Arc USDC this is not a portability nicety, it is free:
///      `0x3600`'s ERC-20 `transfer` MOVES THE NATIVE BALANCE (see {ArgusUnits}),
///      so an ERC-20 transfer of the quote asset and a native send are the same
///      movement. Under any other quote the ERC-20 form is the ONLY movement,
///      which is why {receive} refuses native there. The ERC-20 form is also the
///      one that works when the payout asset is the launched token.
///
///      ------------------------------------------------------------------
///      P-2  NO DECIMALS CONSTANT ANYWHERE ON THE REWARD PATH.
///      ------------------------------------------------------------------
///      The accumulator, `pending`, the bank and every event are denominated in
///      the PAYOUT ASSET'S OWN UNITS. There is no `1e12`, no `SCALE`, no
///      `toNative18` and no 18-decimal assumption in this file, so the contract
///      is decimals-agnostic BY CONSTRUCTION rather than by parameterisation -
///      which is the stronger property, because a parameter can be threaded
///      wrongly and an absent constant cannot.
///      {ArgusDividendTracker} could not do this: its amounts are native 18dp by
///      necessity and its own natspec says so.
///      `decimals()` IS still read once, at {initialize}, and recorded - not to
///      scale anything, but so a payout asset that cannot answer is refused at
///      launch instead of surfacing later, and so an indexer can read the scale
///      of the numbers in the events off the contract.
///      Pinned by `test_D1_quoteDecimalsAreNotAssumed`, which runs the identical
///      distribution against a 6-decimal and an 18-decimal payout asset and
///      asserts each holder is paid in that asset's own units. A hardcoded 1e12
///      anywhere on this path fails one of the two halves by a factor of 1e12.
///
///      ------------------------------------------------------------------
///      P-3  THE EXCLUDED VENUE IS KNOWN AT INITIALIZE. THERE IS NO LAZY
///           DISCOVERY AND NOTHING ON THE TRANSFER PATH TO DISCOVER.
///      ------------------------------------------------------------------
///      {ArgusDividendTracker-_syncPool} staticcalls `token.mainPool()` on every
///      {setShare} until a pool exists, because on v3 the pool address is not
///      known when the tracker is initialized. On v4 the venue is the
///      PoolManager SINGLETON - one address, the same for every launch on the
///      chain, known before any of these contracts are deployed - so it is
///      passed in and excluded here, once. That deletes the staticcall from the
///      hot path and with it the ~113k one-time share update
///      {ArgusTaxToken-SHARE_SYNC_GAS} had to be sized to survive.
///
///      🔴 AND IT IS THE HALF OF THE v4 SINGLETON THAT HELPS. The v3 shape
///      excludes exactly ONE pool, so a rival v3 pool at another fee tier is
///      permanently a shareholder that never claims and permanently dilutes
///      everyone who does. Under v4 every pool on the chain - the launch pool, a
///      rival at another tier, one with a hook - holds its inventory inside this
///      one excluded address, so that entire class is structurally unreachable.
///      The RESIDUAL, stated because it is not zero: a v3 pool for this token on
///      the same chain is a different contract at its own address and WOULD be
///      an unexcluded shareholder. There is no setter to add it and there will
///      not be one; see {isExcluded}.
///
///      ------------------------------------------------------------------
///      P-4  `strandedSince` IS CLEARED AFTER A PAYOUT SUCCEEDS, AND ONLY THEN.
///      ------------------------------------------------------------------
///      `ARC_V4_NOTES.md` §4 blocked this port on a finding against the v3
///      tracker: `strandedSince` was written only inside `reclaimStranded` and
///      cleared only inside its success branch, so a holder that failed one
///      probe and was then paid in full by any other route kept a live marker
///      and lost its whole {STRANDED_GRACE} window.
///
///      🔴 THIS SENTENCE USED TO CITE TWO LINE NUMBERS IN
///      `ArgusDividendTracker.sol` AND SAY THAT CONTRACT "STILL CARRIES THE
///      DEFECT". BOTH HALVES ARE NOW FALSE. `iRedFox/ArgusPad#6` (merge `9e803d8`) remediated that contract
///      and moved the lines. NO LINE NUMBER INTO THAT FILE IS CITED HERE ANY
///      MORE, deliberately: this file does not own it, a merge silently takes
///      its version, and a citation into a file you do not own is a claim with
///      an expiry date nobody is watching. The property, which is checkable
///      without a line number: `ArgusDividendTracker._clearStranded` is now
///      called from FIVE sites covering `claim`, `claimTo`, `_withdrawFor` and
///      `reclaimStranded`.
///
///      THE STATEMENT THIS FILE MAKES ABOUT ITSELF, AND WHAT ENFORCES IT.
///      The clear is ordered AFTER the external send in every one of the four
///      paths that can perform one, so a payout that moves nothing writes
///      nothing. That is stronger than "cleared on every successful payout",
///      and it is the half the original wording did not promise: the original
///      was satisfied by clearing BEFORE a send that does not revert, which is
///      what {_payOrPark} did, and it silently erased the marker on a failure.
///
///      Two enforcement layers, both of which have been shown to fail on the
///      defective code and pass on this one:
///        - BEHAVIOURAL: `AuditP4.test_A1`/`test_A2`/`test_A4`/`test_A6`, with
///          `test_A3` as the in-run control. All four go red when the clear is
///          moved back before the send.
///        - MECHANICAL: `tools/remediate-v4-token/ordering-census.mjs`, which
///          decides from the AST whether each clear precedes or follows its
///          send and whether every field committed before a non-reverting send
///          is restored on the failure path. It is proven by
///          `prove-ordering-census.mjs` on seven cases, including the real
///          pre-remediation v3 tracker.
///      Neither is a comment. `make census` runs the second one.
contract ArgusV4RewardTracker6 is ReentrancyGuard {
    /// @notice Largest batch {distribute} will attempt.
    /// @dev A ceiling, not a target - same reasoning as
    ///      {ArgusDividendTracker-MAX_BATCH}. Size real batches on measured gas.
    uint256 public constant MAX_BATCH = 200;

    /// @notice Ceiling on the dust filter's EFFECT, as a share of total supply.
    /// @dev Verbatim in intent from {ArgusDividendTracker-MAX_MINIMUM_SHARE_BPS}:
    ///      `minimumShareBalance` is creator-chosen, and unbounded it is a funnel
    ///      rather than a filter. Bounded at USE time because at {initialize} the
    ///      token has not minted yet and there is no supply to take a fraction of.
    uint16 public constant MAX_MINIMUM_SHARE_BPS = 10; // 0.1%

    /// @notice Aggregate eligible share that releases a banked deposit.
    uint16 public constant HELD_FLUSH_MIN_SHARE_BPS = 10; // 0.1%

    /// @notice How long a banked deposit may wait on the floor above.
    /// @dev SECONDS. Arc produces a block roughly every 0.506s, so a block count
    ///      carried from another chain means something very different here.
    uint256 public constant HELD_FLUSH_MAX_WAIT = 7 days;

    /// @notice How long a holder must be demonstrably unpayable before
    ///         {reclaimStranded} may fold its rewards back to everyone else.
    uint256 public constant STRANDED_GRACE = 30 days;

    /// @notice 🔴 THERE IS NO PAYOUT GAS STIPEND, AND ITS ABSENCE IS A MEASURED
    ///         DECISION RATHER THAN AN OMISSION. THIS IS P-5.
    ///
    /// @dev {ArgusDividendTracker} caps every batched payout at
    ///      {ArgusConstants-PAYOUT_GAS_STIPEND} and gives a long, correct reason:
    ///      its payout is `to.call{value:}`, which runs the RECIPIENT'S code, so
    ///      one hostile `receive()` can eat 63/64 of a keeper's transaction and a
    ///      recipient reverting with ~96KB of return data can make a 200-holder
    ///      batch unmineable.
    ///
    ///      NONE OF THAT CLASS EXISTS HERE, because of P-1. An ERC-20 `transfer`
    ///      CALLS NO RECIPIENT HOOK - there is no `receive()`, no fallback, no
    ///      `onTokenReceived` on this path - so a recipient cannot spend the
    ///      caller's gas, cannot return data, and cannot refuse. The only code a
    ///      payout runs is the PAYOUT ASSET'S, and that address is fixed at
    ///      {initialize} and is either the quote asset or this launch's own token.
    ///      It is never attacker-chosen.
    ///      `test_P8_anErc20PayoutRunsNoRecipientCode` is the measurement: a
    ///      recipient contract whose every entry point reverts is paid
    ///      successfully.
    ///
    ///      A stipend was written first and then DELETED, for the reason
    ///      `ArgusV4Portal`'s D-5 gives about its own quote-side ceiling - a guard
    ///      that can refuse nothing is not depth, it is furniture. Keeping it was
    ///      also actively harmful: at 60,000 it was BELOW the cost of an in-kind
    ///      payout, which transfers this token and therefore runs two
    ///      {ArgusV4LaunchToken6-SHARE_SYNC_GAS}-bounded share updates, so every
    ///      batched `IN_KIND` payout would have failed and parked. Found by
    ///      `test_K8_distributeWorksInKind` going red, not by review.
    ///
    ///      WHAT IS GIVEN UP, STATED PLAINLY: a per-holder gas bound inside
    ///      {distribute}. So the batch's cost is linear in its size and in the
    ///      payout asset's own cost, and {MAX_BATCH} is a ceiling rather than a
    ///      safe default - measured per-holder costs for both modes are in §6 of
    ///      the report. A keeper sizes batches on those numbers.

    // -------------------------------------------------------------- storage --

    /// @notice The launch token. The only address allowed to move shares.
    address public token;

    /// @notice What holders are paid in. The whole of {RewardMode}, resolved to
    ///         an address at {initialize}. See P-1.
    address public payoutAsset;

    /// @notice The mode this launch was configured with. Stored for disclosure -
    ///         nothing in this contract reads it after {initialize}.
    RewardMode public mode;

    /// @notice `payoutAsset.decimals()`, read once. Recorded, never used to
    ///         scale. See P-2.
    uint8 public payoutDecimals;

    /// @notice The v4 PoolManager. Excluded at {initialize}; see P-3.
    address public venue;

    uint96 public minimumShareBalance;

    bool private _initialized;

    /// @notice When {heldPayout} first became non-zero. Drives {HELD_FLUSH_MAX_WAIT}.
    uint64 public heldSince;

    /// @notice The token's total supply, cached on first successful read.
    /// @dev Lazy for the reason {ArgusDividendTracker-totalSupplyCache} is: the
    ///      token has not minted when this contract is initialized. Safe to
    ///      cache because {ArgusV4LaunchToken6} mints exactly once and has no
    ///      burn and no mint entry point - a property of THAT contract, asserted
    ///      by `test_T3_supplyIsFixedForever`, not an assumption about tokens in
    ///      general.
    uint256 public totalSupplyCache;

    uint256 public accPerShareX128;
    uint256 public totalShares;

    /// @notice Deposits that arrived with nobody eligible to receive them.
    uint256 public heldPayout;

    /// @notice What this contract believes it has been given and still owes out.
    /// @dev THE REASON A PULL-ONLY DEPOSIT IS NOT ENOUGH ON ARC. When the payout
    ///      asset is Arc USDC it is an ERC-20 VIEW onto the native balance, so a
    ///      plain native send to this address raises `payoutAsset.balanceOf(this)`
    ///      with NO ERC-20 call
    ///      to observe - a `deposit()` that only ever pulls could never see value
    ///      forwarded that way, and value nobody can see is value nobody can be
    ///      paid. {syncDeposit} closes it by accounting the difference between
    ///      the real balance and this figure.
    uint256 public accountedBalance;

    uint256 public totalDeposited;
    uint256 public totalPaid;

    /// @notice Settled-but-unpaid rewards. Also where a failed payout lands.
    mapping(address => uint256) public pending;

    /// @notice When {reclaimStranded} first proved `user` unpayable at full gas.
    /// @dev Cleared by {_clearStranded} AFTER a send that actually succeeded, on
    ///      every path that can send - see P-4. The ordering is the claim, not
    ///      merely the presence of a clear: a clear placed before a send that
    ///      parks on failure erases this marker on a payout that moved nothing,
    ///      and that is what shipped. Enforced by `AuditP4` and by
    ///      `ordering-census.mjs` RULE 1; NOT enforced by any set-equality scan,
    ///      which is green in both directions.
    mapping(address => uint64) public strandedSince;

    mapping(address => uint256) private _share;
    mapping(address => uint256) private _debtX128;
    mapping(address => bool) private _excluded;

    // --------------------------------------------------------------- events --

    event ShareUpdated(address indexed user, uint256 oldShare, uint256 newShare);
    event Deposited(uint256 amount, uint256 accPerShareX128);
    event DepositHeld(uint256 amount, uint256 totalHeld);
    event DepositHeldReleased(uint256 amount, uint256 totalShares);
    event Paid(address indexed user, address indexed destination, uint256 amount);
    event PayFailed(address indexed user, uint256 amount);
    event Excluded(address indexed account);
    event StrandedProbed(address indexed user, uint256 amount, uint256 redistributableAt);
    event StrandedRedistributed(address indexed user, uint256 amount, uint256 totalShares);

    // --------------------------------------------------------------- errors --

    error BatchTooLarge();
    error NothingToClaim();
    error BankNotReleasable();
    error NotAContract();
    error PayoutFailed();
    error NothingDeposited();
    /// @dev The payout asset does not answer `decimals()`, or answers with more
    ///      than 18. Refused at launch rather than tolerated: an asset whose
    ///      scale cannot be read is one whose event stream cannot be interpreted.
    error PayoutAssetUnreadable();

    /// @dev A tracker was initialized with `RewardMode.NONE`. Not a
    ///      configuration this contract can express: `NONE` means the token
    ///      clones no tracker at all, so reaching {initialize} with it is a wiring
    ///      bug in the caller rather than a creator's choice.
    error RewardsDisabled();

    /// @dev A native send reached a tracker whose payout asset is not native.
    ///      See {receive}.
    error NativeNotThePayoutAsset();

    // ------------------------------------------------------------ lifecycle --

    /// @dev Locks the implementation. A clone gets fresh storage and initializes
    ///      normally; the implementation can never be initialized, so nobody can
    ///      claim the address every clone points at. This is
    ///      {ArgusDividendTracker}'s audit finding L-4 taken as a starting
    ///      condition rather than as a fix.
    constructor() {
        _initialized = true;
    }

    /// @param token_ the launch token; the only address that may move shares
    /// @param payoutAsset_ what holders are paid in - the launch's own quote asset
    ///        in `RewardMode.QUOTE`, `token_` itself in `RewardMode.IN_KIND`
    /// @param venue_ the v4 PoolManager singleton. Excluded here; see P-3.
    /// @param exempt addresses the launch needs excluded that this contract cannot
    ///        work out for itself. {ArgusV4LaunchToken6} passes the PORTAL plus
    ///        whatever the Portal's own `extraExempt` carried - on a real launch
    ///        that is the fee locker, which is paid the token side of the LP fees
    ///        straight out of the PoolManager and must not be a shareholder.
    ///        The token passes the SAME list it writes into its own `isExempt`, so
    ///        the two sets are equal by construction rather than by agreement;
    ///        `test_E4_theTwoExclusionSetsAgree` pins it.
    function initialize(
        address token_,
        address payoutAsset_,
        address venue_,
        RewardMode mode_,
        uint96 minimumShareBalance_,
        address[] calldata exempt
    ) external {
        if (_initialized) revert ArgusErrors.AlreadyInitialized();
        if (token_ == address(0) || payoutAsset_ == address(0) || venue_ == address(0)) {
            revert ArgusErrors.ZeroAddress();
        }
        if (mode_ == RewardMode.NONE) revert RewardsDisabled();
        _initialized = true;

        token = token_;
        payoutAsset = payoutAsset_;
        venue = venue_;
        mode = mode_;
        minimumShareBalance = minimumShareBalance_;

        // READ, RECORDED, NEVER USED TO SCALE. See P-2. A `try` rather than a
        // bare call because a payout asset that cannot answer must fail the
        // launch here, loudly, and not later inside a distribution.
        try IERC20Decimals(payoutAsset_).decimals() returns (uint8 d) {
            if (d > 18) revert PayoutAssetUnreadable();
            payoutDecimals = d;
        } catch {
            revert PayoutAssetUnreadable();
        }

        _excluded[address(this)] = true;
        _excluded[token_] = true;
        _excluded[venue_] = true;
        _excluded[ArgusConstants.DEAD] = true;
        _excluded[address(0)] = true;
        for (uint256 i; i < exempt.length; ++i) {
            if (exempt[i] != address(0)) _excluded[exempt[i]] = true;
        }
    }

    // ----------------------------------------------------------- share hooks --

    /// @notice Record `user`'s post-transfer balance as its share.
    ///
    /// @dev Settles against this contract's OWN stored share, never the `balance`
    ///      argument - {ArgusDividendTracker}'s departure 1, for the same reason:
    ///      `balance` is the POST-transfer figure and settling against it would
    ///      reprice the window that just closed.
    ///
    ///      🔴 THIS FUNCTION IS REACHED REENTRANTLY IN `IN_KIND` MODE AND THAT IS
    ///      THE MOST DANGEROUS THING IN THIS FILE. An in-kind payout is a
    ///      transfer of the launched token, so {_payOrPark} calls the token, the
    ///      token calls back here, and this runs INSIDE the payout.
    ///
    ///      WHAT ACTUALLY MAKES IT SAFE IS THE `_settle` AT THE TOP OF
    ///      {_payOrPark}, NOT THE ORDER OF THE LINES AFTER IT - and an earlier
    ///      version of this comment said the opposite. That settle advances
    ///      `_debtX128[user]` to `accPerShareX128`, so when the reentrant call
    ///      arrives {_settle} returns on its FIRST line and there is nothing to
    ///      double-credit no matter where `pending` was zeroed.
    ///      MEASURED, and it is why the claim was rewritten: mutant
    ///      `R1-pending-zeroed-after-the-transfer` moves the zeroing to AFTER the
    ///      transfer and SURVIVES the whole suite. Zeroing first is real depth -
    ///      it is what would still hold if the settle were ever removed - but it
    ///      is not the thing doing the work today, and a single-line mutation
    ///      cannot see through the two. The COMPOUND
    ///      `R1b-compound-no-settle-and-pending-zeroed-late` removes both and is
    ///      the mutant that measures the stack, exactly as
    ///      `ArgusV4Portal`'s D-5 uses M20 against its own four layers.
    ///      `test_K5_inKindPayoutCannotDoubleCredit` drives the live path and
    ///      asserts the conservation law the reentrancy would break.
    ///
    ///      This is deliberately NOT solved with a reentrancy guard: blocking the
    ///      callback would make the token's own `_update` revert and take the
    ///      payout with it.
    function setShare(address user, uint256 balance) external {
        if (msg.sender != token) revert ArgusErrors.OnlyToken();

        uint256 newShare = (_excluded[user] || balance < _effectiveMinShare()) ? 0 : balance;
        uint256 oldShare = _share[user];

        // Nothing to do, and nothing lost by skipping the settle: accrual is
        // linear in a share that did not change.
        if (newShare == oldShare) return;

        _settle(user);

        _share[user] = newShare;
        totalShares = totalShares - oldShare + newShare;

        emit ShareUpdated(user, oldShare, newShare);
    }

    /// @notice The dust filter actually in force: the configured value, capped at
    ///         {MAX_MINIMUM_SHARE_BPS} of total supply.
    /// @dev Fails toward INCLUSION - an unreadable supply drops the filter rather
    ///      than applying it unbounded, so an unreadable supply can never be the
    ///      thing that concentrates rewards.
    function _effectiveMinShare() internal returns (uint256) {
        uint256 configured = minimumShareBalance;
        if (configured == 0) return 0;

        uint256 supply = _supply();
        if (supply == 0) return 0;

        uint256 cap = (supply * MAX_MINIMUM_SHARE_BPS) / ArgusConstants.BPS;
        return configured > cap ? cap : configured;
    }

    function _supply() internal returns (uint256) {
        uint256 cached = totalSupplyCache;
        if (cached != 0) return cached;

        (bool ok, bytes memory ret) = token.staticcall(abi.encodeWithSelector(IERC20.totalSupply.selector));
        if (!ok || ret.length < 32) return 0;

        uint256 supply = abi.decode(ret, (uint256));
        if (supply != 0) totalSupplyCache = supply;
        return supply;
    }

    /// @dev Removes an address from the denominator for good. Settles first: a
    ///      reward it earned while eligible is genuinely its own and stays
    ///      claimable.
    function _exclude(address account) internal {
        if (_excluded[account]) return;
        _excluded[account] = true;
        emit Excluded(account);

        uint256 oldShare = _share[account];
        if (oldShare == 0) return;

        _settle(account);
        _share[account] = 0;
        totalShares -= oldShare;

        emit ShareUpdated(account, oldShare, 0);
    }

    function _settle(address account) internal {
        uint256 perShare = accPerShareX128;
        uint256 debt = _debtX128[account];
        if (debt == perShare) return;

        _debtX128[account] = perShare;

        uint256 shares = _share[account];
        if (shares == 0) return;

        pending[account] += (shares * (perShare - debt)) >> 128;
    }

    // -------------------------------------------------------------- deposits --

    /// @notice Pull `amount` of the payout asset from the caller and distribute it.
    function deposit(uint256 amount) external nonReentrant {
        if (amount == 0) revert NothingDeposited();
        address asset = payoutAsset;

        uint256 before = IERC20(asset).balanceOf(address(this));
        // `transferFrom`, not `safeTransferFrom`: the received amount is measured
        // rather than assumed, so a fee-on-transfer payout asset is accounted at
        // what actually arrived instead of at what was asked for.
        (bool ok, bytes memory ret) = asset.call(
            abi.encodeWithSelector(IERC20.transferFrom.selector, msg.sender, address(this), amount)
        );
        if (!ok || (ret.length != 0 && !abi.decode(ret, (bool)))) revert PayoutFailed();

        uint256 received = IERC20(asset).balanceOf(address(this)) - before;
        if (received == 0) revert NothingDeposited();

        accountedBalance += received;
        _deposit(received);
    }

    /// @notice Distribute any balance this contract holds but has not yet
    ///         accounted for.
    /// @dev Permissionless and idempotent. MANDATORY on Arc rather than
    ///      convenient - see {accountedBalance}.
    function syncDeposit() external nonReentrant returns (uint256 amount) {
        uint256 real = IERC20(payoutAsset).balanceOf(address(this));
        uint256 known = accountedBalance;
        if (real <= known) revert NothingDeposited();

        amount = real - known;
        accountedBalance = real;
        _deposit(amount);
    }

    /// @notice Whether the banked balance may be released to current holders.
    /// @dev Two ways to qualify, and the second exists so the first can never be
    ///      a permanent lock. Identical rule for both callers, deliberately - an
    ///      on-demand exit under a weaker rule would be a second rule.
    function _bankReleasable(uint256 currentShares) internal returns (bool) {
        uint64 since = heldSince;
        if (since != 0 && block.timestamp >= uint256(since) + HELD_FLUSH_MAX_WAIT) return true;

        uint256 supply = _supply();
        if (supply == 0) return true;

        return currentShares >= (supply * HELD_FLUSH_MIN_SHARE_BPS) / ArgusConstants.BPS;
    }

    function _deposit(uint256 amount) internal {
        if (amount == 0) return;
        totalDeposited += amount;

        uint256 shares = totalShares;

        if (shares == 0) {
            // Nobody eligible holds anything. Do NOT advance the checkpoint:
            // dividing by a supply that does not exist burns the deposit instead
            // of banking it for whoever holds next.
            if (heldPayout == 0) heldSince = uint64(block.timestamp);
            heldPayout += amount;
            emit DepositHeld(amount, heldPayout);
            emit Deposited(amount, accPerShareX128);
            return;
        }

        uint256 total = amount;
        uint256 bank = heldPayout;
        if (bank != 0 && _bankReleasable(shares)) {
            total += bank;
            heldPayout = 0;
            heldSince = 0;
            emit DepositHeldReleased(bank, shares);
        }

        // The division truncates and the lost wei STAYS here rather than being
        // carried forward. Carrying it is the residual-carry bug
        // {ArgusDividendTracker-_deposit} documents: a holder settles many
        // deposits at once and one floor over the summed growth recovers wei that
        // each per-deposit floor had given away, so both sides claim it and the
        // shortfall surfaces as the last claimer's payout failing.
        accPerShareX128 += (total << 128) / shares;

        emit Deposited(total, accPerShareX128);
    }

    /// @notice Release a banked deposit on demand, with no further deposit needed.
    function flushBank() external nonReentrant returns (uint256 released) {
        uint256 bank = heldPayout;
        uint256 shares = totalShares;
        if (bank == 0 || shares == 0 || !_bankReleasable(shares)) revert BankNotReleasable();

        heldPayout = 0;
        heldSince = 0;
        accPerShareX128 += (bank << 128) / shares;

        emit DepositHeldReleased(bank, shares);
        emit Deposited(bank, accPerShareX128);
        return bank;
    }

    // --------------------------------------------------------------- payouts --

    function withdrawableOf(address user) public view returns (uint256) {
        uint256 shares = _share[user];
        uint256 accrued = shares == 0 ? 0 : (shares * (accPerShareX128 - _debtX128[user])) >> 128;
        return pending[user] + accrued;
    }

    /// @notice Pay the caller. Parks on failure rather than reverting.
    function withdraw() external nonReentrant returns (uint256) {
        return _payOrPark(msg.sender, msg.sender);
    }

    /// @notice Pay `user`. The keeper path, and identical to {withdraw} - see P-5
    ///         for why there is no capped variant.
    function withdrawFor(address user) external nonReentrant returns (uint256) {
        return _payOrPark(user, user);
    }

    /// @notice Pay the caller, forwarding all gas, and REVERT if it fails.
    /// @dev The single-address escape hatch for a holder the batch path cannot
    ///      pay. Reverting rather than parking is correct here: a caller asking
    ///      for its own money is entitled to learn that it did not arrive.
    function claim() external nonReentrant returns (uint256 amount) {
        _settle(msg.sender);
        amount = pending[msg.sender];
        if (amount == 0) revert NothingToClaim();

        pending[msg.sender] = 0;
        totalPaid += amount;
        accountedBalance -= amount;

        if (!_transfer(payoutAsset, msg.sender, amount)) revert PayoutFailed();
        _clearStranded(msg.sender);
        emit Paid(msg.sender, msg.sender, amount);
    }

    /// @notice Rescue the caller's own rewards to a different address.
    /// @dev The exit for a holder that cannot itself receive - a blocked address,
    ///      a contract with no `receive()`. It moves only value already settled
    ///      to `msg.sender` and pays nobody else.
    function claimTo(address destination) external nonReentrant returns (uint256 amount) {
        if (destination == address(0)) revert ArgusErrors.ZeroAddress();

        _settle(msg.sender);
        amount = pending[msg.sender];
        if (amount == 0) revert NothingToClaim();

        pending[msg.sender] = 0;
        totalPaid += amount;
        accountedBalance -= amount;

        if (!_transfer(payoutAsset, destination, amount)) revert PayoutFailed();
        _clearStranded(msg.sender);
        emit Paid(msg.sender, destination, amount);
    }

    /// @notice Pay a batch of holders. Never reverts because one of them failed.
    function distribute(address[] calldata users) external nonReentrant returns (uint256 paidCount) {
        if (users.length > MAX_BATCH) revert BatchTooLarge();
        for (uint256 i; i < users.length; ++i) {
            if (_payOrPark(users[i], users[i]) != 0) ++paidCount;
        }
    }

    /// @dev Settle, snapshot, ZERO, then move - and the order is load-bearing in
    ///      `IN_KIND` mode. See the note on {setShare}.
    ///
    ///      🔴 THE PARK BRANCH IS A HAND-WRITTEN ROLLBACK, AND IT MUST STAY
    ///      COMPLETE. It restores `pending`, `totalPaid` and `accountedBalance`
    ///      - exactly the three fields committed above the send. It once had to
    ///      restore a fourth, `strandedSince`, and did not; the fix was to stop
    ///      committing that field early rather than to lengthen this list.
    ///      ANY NEW FIELD WRITTEN BETWEEN `pending[user] = 0` AND THE SEND MUST
    ///      EITHER BE RESTORED HERE OR BE MOVED INSIDE THE SUCCESS BRANCH.
    ///      `ordering-census.mjs` RULE 1 fails the build if it is neither, and
    ///      its M3 case is precisely that mistake made on purpose.
    function _payOrPark(address user, address destination) internal returns (uint256 amount) {
        if (user == address(0)) return 0;

        _settle(user);

        amount = pending[user];
        if (amount == 0) return 0;

        pending[user] = 0;
        totalPaid += amount;
        accountedBalance -= amount;

        if (_transfer(payoutAsset, destination, amount)) {
            _clearStranded(user);
            emit Paid(user, destination, amount);
            return amount;
        }

        // Park, never revert. When the payout asset is Arc USDC it is a view onto
        // the native balance and the node enforces a sanctions blocklist BELOW the
        // EVM on native movement, so a payout to a blocked holder fails however
        // this is written - and any other quote may carry a blocklist of its own.
        // Bubbling it would take the other 199 holders down too.
        pending[user] = amount;
        totalPaid -= amount;
        accountedBalance += amount;
        emit PayFailed(user, amount);
        return 0;
    }

    /// @dev P-4. CALL THIS AFTER THE SEND, NEVER BEFORE IT. Every caller does,
    ///      and that is the property: a holder that was once unpayable and has
    ///      since been paid starts a fresh {STRANDED_GRACE} window on its next
    ///      failure, while a holder whose payout FAILED keeps the window it
    ///      already had.
    ///
    ///      The two callers that revert on failure ({claim}, {claimTo}) would be
    ///      safe either way, because the revert rolls the write back. They still
    ///      clear after the send, and that uniformity is deliberate: {_payOrPark}
    ///      IS {claim} with the revert replaced by a park, and that single edit
    ///      is what turned a safe ordering into a money defect. Leaving the
    ///      exception in place leaves the trap loaded for whoever makes that
    ///      edit next.
    function _clearStranded(address user) internal {
        if (strandedSince[user] != 0) strandedSince[user] = 0;
    }

    /// @dev ONE exit for every payout in this contract, in either mode, forwarding
    ///      all gas. See P-5 for why there is no cap.
    ///
    ///      The return data is discarded rather than copied, and that is a
    ///      griefing fix rather than a style choice - the reasoning is
    ///      {ArgusDividendTracker-_withdrawFor}'s and it applies unchanged: a
    ///      recipient that reverts with ~96KB of return data forces THIS contract
    ///      to expand its own memory inside a batch loop, and memory is priced
    ///      n^2/512. The high-level `IERC20.transfer` copies it. This does not.
    ///
    ///      A token that returns nothing is a valid ERC-20; one that returns
    ///      `false` is a failure that did not revert. Both are handled, or a
    ///      "successful" payout moves nothing and marks a holder paid.
    function _transfer(address asset, address to, uint256 amount) internal returns (bool) {
        bytes memory data = abi.encodeWithSelector(IERC20.transfer.selector, to, amount);
        bool ok;
        uint256 retSize;
        bytes32 word;
        assembly ("memory-safe") {
            // (gas, address, value, inOffset, inSize, outOffset, outSize).
            // outSize 32: exactly one word is kept, which is all an ERC-20 bool
            // can be, and the rest of a return is never copied - the memory-cost
            // half of the v3 griefing note survives P-5 because it is about what
            // THIS contract is billed, not about what the callee spends.
            ok := call(gas(), asset, 0, add(data, 0x20), mload(data), 0, 0x20)
            retSize := returndatasize()
            word := mload(0)
        }
        if (!ok) return false;
        if (retSize == 0) return true;
        return word != bytes32(0);
    }

    /// @notice Accept a native send, but ONLY when the payout asset is Arc USDC -
    ///         the one ERC-20 whose balance IS the native balance.
    ///
    /// @dev THIS IS AN ARC FACT, NOT A CONVENIENCE. `0x3600` is an ERC-20 VIEW
    ///      onto the native balance, so for a USDC payout "send someone quote" and
    ///      "send someone native" are the same movement - and the contract that
    ///      pays LP fees on the older Portals, {ArgusV4FeeLocker-_push}, pays by
    ///      `to.call{value:}`. A USDC tracker with no `receive()` would refuse the
    ///      chain's primary value transfer.
    ///
    ///      THE GUARD IS ON THE ASSET, NOT ON THE MODE, AND THAT IS THIS COPY'S ONE
    ///      CHANGE. The original refused native unless `mode == QUOTE`, reading
    ///      QUOTE as "native". Portal #6 hands a QUOTE tracker the launch's own
    ///      quote, which need not be USDC; native arriving at such a tracker would
    ///      raise a balance {syncDeposit} does not read (it reads
    ///      `payoutAsset.balanceOf`) and {_transfer} cannot move - and this
    ///      contract has no owner, no sweep and no rescue, so it would be stranded
    ///      permanently. Value this contract cannot pay out, it does not accept.
    ///
    ///      Every case the original decided, this decides the same way: a USDC
    ///      QUOTE tracker accepts; an `IN_KIND` tracker (payout asset = the
    ///      launched token) refuses; the un-initialized implementation (payout
    ///      asset = zero) refuses. The one case that moves is QUOTE under a
    ///      non-USDC quote, from accept-and-strand to refuse. Pinned by the
    ///      `test_N*` cases in `ArgusV4LaunchToken6.t.sol`, whose in-run control
    ///      is the ORIGINAL tracker accepting and stranding the same send.
    ///
    ///      An ERC-20 `transfer` of the payout asset does NOT come through here -
    ///      it runs no recipient code, and for `0x3600` Arc moves the balance below
    ///      the EVM - so {syncDeposit} remains the general answer and this is the
    ///      specific one. Neither is redundant: an ERC-20 transfer cannot be
    ///      refused, and a native send cannot be accounted without a sync.
    receive() external payable {
        if (payoutAsset != ArgusUnits.USDC) revert NativeNotThePayoutAsset();
    }

    // -------------------------------------------------------------- stranded --

    /// @notice Prove a contract holder cannot be paid at FULL gas, and after
    ///         {STRANDED_GRACE} fold its rewards back to everyone else.
    ///
    /// @dev Contracts only. An EOA can always sign, so {claimTo} is its exit and
    ///      it is never eligible.
    function reclaimStranded(address user)
        external
        nonReentrant
        returns (uint256 paid, uint256 redistributed)
    {
        if (user.code.length == 0) revert NotAContract();

        _settle(user);
        uint256 amount = pending[user];
        if (amount == 0) revert NothingToClaim();

        pending[user] = 0;

        // FULL gas, so a failure here is a fact about the recipient rather than
        // about the budget the caller chose.
        if (_transfer(payoutAsset, user, amount)) {
            totalPaid += amount;
            accountedBalance -= amount;
            _clearStranded(user);
            emit Paid(user, user, amount);
            return (amount, 0);
        }

        // `+=` rather than `=`: assignment would clobber a credit that arrived by
        // another route, and this is the branch where being wrong loses a
        // holder's money.
        pending[user] += amount;

        uint64 since = strandedSince[user];
        if (since == 0) {
            strandedSince[user] = uint64(block.timestamp);
            emit StrandedProbed(user, amount, block.timestamp + STRANDED_GRACE);
            return (0, 0);
        }

        uint256 readyAt = uint256(since) + STRANDED_GRACE;
        if (block.timestamp < readyAt) {
            emit StrandedProbed(user, amount, readyAt);
            return (0, 0);
        }

        pending[user] -= amount;

        // BEFORE the fold: a holder still in the denominator would earn back a
        // slice of its own reclaimed rewards and strand that slice too.
        _exclude(user);

        uint256 remaining = totalShares;
        if (remaining == 0) {
            if (heldPayout == 0) heldSince = uint64(block.timestamp);
            heldPayout += amount;
            emit DepositHeld(amount, heldPayout);
        } else {
            accPerShareX128 += (amount << 128) / remaining;
        }

        emit StrandedRedistributed(user, amount, remaining);
        return (0, amount);
    }

    // ----------------------------------------------------------------- views --

    function shareOf(address user) external view returns (uint256) {
        return _share[user];
    }

    /// @notice Whether `account` is out of the reward denominator.
    /// @dev THERE IS NO SETTER AND THERE WILL NOT BE ONE. The set is what
    ///      {initialize} wrote plus whatever {reclaimStranded} has proven
    ///      unpayable. A permissioned exclusion setter is the funnel
    ///      {MAX_MINIMUM_SHARE_BPS} exists to bound, handed an owner - and this
    ///      line has no owner anywhere in it. The cost is named in P-3.
    function isExcluded(address account) external view returns (bool) {
        return _excluded[account];
    }
}

