// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/// @title ArgusUnits
/// @notice The one place that knows Arc's native asset has two decimal scales.
///
/// Arc's gas token IS USDC, and it is reachable two ways that are the SAME
/// BALANCE, not two assets:
///
///   - natively, at **18 decimals** (`address(x).balance`, `msg.value`)
///   - through an ERC-20 view at `0x3600...0000`, at **6 decimals**
///
/// Verified on Arc mainnet against live addresses: for the STEVE/USDC pool,
/// `balance` was 31622011506000000000000 and `balanceOf` was 31622011506 -
/// exactly 1e12 apart. In a real swap every `0x3600` Transfer is mirrored by an
/// EIP-7708 native log at the same 1e12 ratio, so an ERC-20 `transfer` moves the
/// native balance and receiving `msg.value` credits `balanceOf`. There is no
/// wrap step, no `deposit()`, no `withdraw()`. (That is exactly why the Uniswap
/// SwapRouter02 on Arc points `WETH9()` at a 53-byte stub that reverts on every
/// call - nothing needs it.)
///
/// The asymmetry that bites: a **native** transfer can move any wei amount, but
/// the **ERC-20 view cannot represent anything below 1e12**. So every value that
/// crosses into an ERC-20 call (a swap, an approve) must be floored to a 1e12
/// multiple, with the remainder retained rather than assumed away. Rounding the
/// other way promises out more than the contract holds, which surfaces as the
/// final claimer reverting - the classic residual-carry bug.
///
/// Amounts carry their scale in the name everywhere in this codebase:
/// `...Native18` or `...Usdc6`. A wrong scale is otherwise invisible and will
/// pass a test that is wrong in the same direction.
library ArgusUnits {
    /// @dev Arc's ERC-20 view onto the native USDC balance. 6 decimals.
    address internal constant USDC = 0x3600000000000000000000000000000000000000;

    /// @dev 10 ** (18 - 6). Native wei per one ERC-20 unit.
    uint256 internal constant SCALE = 1e12;

    /// @notice Native (18dp) -> ERC-20 view (6dp), rounding DOWN.
    /// @dev Down is not a preference, it is the safe direction: the result is
    ///      about to be handed to a contract that will actually move it.
    function toUsdc6(uint256 amountNative18) internal pure returns (uint256) {
        return amountNative18 / SCALE;
    }

    /// @notice ERC-20 view (6dp) -> native (18dp). Always exact.
    function toNative18(uint256 amountUsdc6) internal pure returns (uint256) {
        return amountUsdc6 * SCALE;
    }

    /// @notice The largest 1e12 multiple at or below `amountNative18`, plus what
    ///         was left over.
    /// @dev Use before any swap or approve: send `spendableNative18`, keep
    ///      `dustNative18` on the books so it is neither double-counted nor lost.
    ///      It will be swept into a later swap-back once enough accumulates.
    function splitDust(uint256 amountNative18)
        internal
        pure
        returns (uint256 spendableNative18, uint256 dustNative18)
    {
        unchecked {
            dustNative18 = amountNative18 % SCALE;
            spendableNative18 = amountNative18 - dustNative18;
        }
    }

    /// @notice True when `amountNative18` survives a round-trip through the
    ///         6-decimal view without loss.
    function isRepresentable(uint256 amountNative18) internal pure returns (bool) {
        return amountNative18 % SCALE == 0;
    }
}

