// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";

import {ArgusConstants, ArgusErrors} from "./types/ArgusTypes.sol";
import {ArgusV4LaunchConfig, RewardMode} from "./ArgusV4LaunchConfig.sol";
import {ArgusV4RewardTracker6} from "./ArgusV4RewardTracker6.sol";
import {IArgusV4LaunchToken7} from "./interfaces/IArgusV4LaunchToken7.sol";

/// @title ArgusV4LaunchToken7
/// @notice The `tokenImpl` for {ArgusV4Portal7}: {ArgusV4LaunchToken6} with the
///         reward PAYOUT asset passed separately from the PAIRING asset.
///
/// @dev ------------------------------------------------------------------
///      WHAT CHANGED FROM #6, AND NOTHING ELSE DID
///      ------------------------------------------------------------------
///      A copy of {ArgusV4LaunchToken6}, Portal #6's deployed `tokenImpl`, which
///      is not edited. Three changes (SPEC_PORTAL7.md §2.1):
///
///        1. {initialize} takes a TENTH argument, `payoutAsset_`, and a
///           `RewardMode.QUOTE` tracker pays in THAT rather than in the ninth,
///           `quoteAsset_`. Portal #7 passes the pool quote when the quote is
///           keep-listed and USDC when it is not (SPEC_QUOTE_AUTO_ADMISSION.md
///           §5b). {quoteAsset} still stores the ninth argument, so it still
///           answers what the pool is paired against. That is the whole reason
///           this contract exists instead of reusing #6's token with USDC as its
///           ninth argument (qa-11 §2.3, option ii, the owner's ruling).
///        2. `payoutAsset_` must be `quoteAsset_` or {defaultQuoteAsset}, and is
///           refused otherwise ({PayoutAssetNotAllowed}). Those are the only two
///           values Portal #7 passes, and a tracker paying a third asset could
///           not be funded by the splitter, which pays holders only in the quote,
///           in USDC, or in the token.
///        3. `extraExempt` is `memory`, for the stack. See {initialize}.
///
///      THE TRACKER IS UNCHANGED. The constructor creates the same
///      {ArgusV4RewardTracker6} Portal #6's token creates. Its {receive} accepts
///      native only when its payout asset is Arc USDC, which under Portal #7 is
///      true of every non-keep QUOTE launch as well as of every USDC one.
///
///      THE TESTS NAMED BELOW RUN AGAINST THE ORIGINALS. Every `test_*` cited in
///      the text carried over from #6 and #5 was written against those contracts.
///      What executes against THIS contract is
///      `test/unit/ArgusV4LaunchToken7.t.sol`, which ports #6's nineteen and adds
///      the payout-argument cases and the no-mint and no-owner-power guarantees.
///
///      ------------------------------------------------------------------
///      #6's HEADER, CARRIED OVER
///      ------------------------------------------------------------------
///      {ArgusV4LaunchToken} WITH THE QUOTE MOVED FROM THE IMPLEMENTATION TO THE
///      CLONE. That contract is Portal #5's deployed `tokenImpl` and is not
///      edited; this is a copy (SPEC_PORTAL6.md §2.5). The original holds
///      `quoteAsset` as an IMMUTABLE, so every clone reads one value, and its
///      `_wireRewards` makes that value the payout asset of every
///      `RewardMode.QUOTE` tracker. Behind a Portal that admits a quote per
///      launch, that is a dividend paid in USDC by a launch that only ever
///      collects its own quote. Four changes, and nothing else differs:
///
///        1. The immutable stays, renamed {defaultQuoteAsset}: the quote this
///           implementation was built for, and the one value a Portal can check
///           at deploy. NOTHING in this contract reads it after the constructor.
///        2. {initialize} takes a NINTH argument, `quoteAsset_`, stored per clone
///           as {quoteAsset} and handed to {_wireRewards}. A QUOTE tracker pays
///           in THAT. The selector moves from `0xc4ee371e` to `0x92e481f4`,
///           fixed by {IArgusV4LaunchToken6}, which this contract inherits.
///        3. The tracker implementation is CREATED by the constructor, not passed
///           in. {ArgusV4RewardTracker6-initialize} has the same selector as the
///           original tracker's, so a deploy that handed this token the OLD
///           tracker would compile, deploy and launch, and the only symptom would
///           be native stranded in a non-USDC QUOTE tracker. With no argument
///           there is nothing to hand it. Read the address from {trackerImpl}.
///        4. The tracker is {ArgusV4RewardTracker6}, whose {receive} accepts
///           native only when the payout asset is Arc USDC.
///
///      The exemption set is unchanged and is written exactly as before.
///
///      THE TESTS NAMED BELOW RUN AGAINST THE ORIGINAL. Every `test_*` cited in
///      the text carried over from {ArgusV4LaunchToken} was written against that
///      contract and still executes against it. They describe this code because
///      it is that code outside the four changes; they do not execute it. What
///      executes against THIS contract is `test/unit/ArgusV4LaunchToken6.t.sol`.
///
///      ------------------------------------------------------------------
///      THE THREE BINDING REQUIREMENTS, QUOTED AND SATISFIED
///      ------------------------------------------------------------------
///      `ArgusV4Portal`'s note on {IArgusV4LaunchToken} states them:
///
///        "THREE binding requirements on any `tokenImpl` follow, and the third is
///         easy to miss: it must mint EXACTLY `totalSupply` and no more, in
///         `initialize`; it must not inflate during the mint; and IT MUST NOT
///         TREAT `0x...dEaD` AS A BURN ADDRESS"
///
///      R1 - MINT EXACTLY `totalSupply`, IN `initialize`. {initialize} calls
///      `_mint(supplyRecipient, totalSupply_)` exactly once and there is no other
///      `_mint` in this contract. Pinned by `test_R1_exactSupplyIsMinted`.
///
///      R2 - DO NOT INFLATE DURING THE MINT. {_update} moves balances and calls
///      the tracker; it never mints, and this contract has NO mint entry point of
///      any kind - not owner-gated, not portal-gated, none. Pinned by
///      `test_R2_totalSupplyIsConstantAcrossTheWholeLaunch`, which reads
///      `totalSupply()` before and after a real Portal launch.
///
///      R3 - `0x...dEaD` IS AN ORDINARY HOLDER. It is deliberately NOT special
///      anywhere in this file: no burn-on-transfer, no `_burn`, no exclusion from
///      `totalSupply()`. `ArgusV4Portal._mintCurve` transfers the rounding residue
///      there BEFORE reading the anchor, so a token that
///      burned on transfer to that address would fail `SupplyNotAnchored` on EVERY
///      launch - the Portal measured the largest residue at 254,169,568 wei out of
///      1e27. Pinned by `test_R3_deadIsAnOrdinaryHolder`.
///
///      🔴 AND THE ANCHOR IS A CONSISTENCY CHECK, NOT AN HONESTY CHECK, SO THE
///      REQUIREMENTS ABOVE ARE NOT WHAT MAKES THIS TOKEN SAFE. The same note is
///      explicit that a `tokenImpl` reporting the asked-for supply while
///      crediting ten times that to the creator launches cleanly, and that an
///      implementation with a mint entry point can dilute the curve in the SAME
///      transaction. Those are properties of the implementation and this is the
///      implementation, so they are answered here rather than by the Portal:
///      exactly one `_mint`, to exactly the address the Portal names, and no
///      second credit to anybody. `test_H1_noHiddenPremint` and
///      `test_H2_noMintEntryPointExists` are the two that hold it.
///
///      ------------------------------------------------------------------
///      NO TRANSFER TAX, AND IT IS NOT A PREFERENCE
///      ------------------------------------------------------------------
///      A transfer-based tax cannot survive Uniswap v4. A trader may take swap
///      proceeds as an ERC-6909 CLAIM against the PoolManager, in which case no
///      ERC-20 `transfer` of this token happens at all, {_update} never runs, and
///      a tax jar stays empty. Re-measured for this contract at the pin in
///      `V4_LAUNCH_TOKEN_REPORT.md` §2, with a positive control in the same run:
///      the identical token taxes an ERC-20-settled swap and does not tax a
///      claim-settled one, so the instrument can detect a tax and the absence is
///      a finding rather than a silence.
///      So the tax is not implemented, disabled or left at zero - it is ABSENT,
///      and the reward stream is funded from outside this contract instead. See
///      {ArgusV4RewardTracker6-deposit} and §5 of the report.
///
///      ------------------------------------------------------------------
///      IMMUTABLES HERE, AND WHY THAT IS THE OPPOSITE OF `ArgusTaxToken`
///      ------------------------------------------------------------------
///      `ArgusTaxToken`'s header says "Nothing here is `immutable`" because an
///      immutable lives in the IMPLEMENTATION's runtime code, so every clone reads
///      the implementation's value - the same tax rate, the same creator wallet,
///      on every launch. That reasoning is correct and it is about PER-LAUNCH
///      config. The four immutables below are per-DEPLOYMENT constants: the same
///      tracker implementation, the same PoolManager, the same DEFAULT quote and
///      the same config registry for every launch this pad will ever do. For
///      those, a clone reading the implementation's value is exactly the wanted
///      behaviour and it saves cold SLOADs on every launch.
///      THE LAUNCH'S QUOTE IS NO LONGER ONE OF THEM, and that is `ArgusTaxToken`'s
///      reasoning applied rather than overturned: once a Portal admits a quote per
///      launch, the quote is per-launch config, and per-launch config lives in
///      storage. On the original it was an immutable because its Portal could only
///      ever name one.
///      That a clone really does read the four is not assumed:
///      `test_C1_aCloneReadsTheImplementationsImmutables` asserts it.
///      Everything that varies per launch - name, symbol, supply, owner, reward
///      mode, quote - is in storage, written once by {initialize}.
contract ArgusV4LaunchToken7 is ERC20, IArgusV4LaunchToken7 {
    /// @dev Gas ceiling on each {ArgusV4RewardTracker6-setShare}.
    ///
    ///      LOWER THAN {ArgusTaxToken-SHARE_SYNC_GAS}'s 200,000 ON PURPOSE, and
    ///      the reason is P-3 of the tracker: the ~113k path where the v3 tracker
    ///      first LEARNS the pool address and un-counts a share it had already
    ///      credited does not exist here, because the excluded venue is passed in
    ///      at initialize and there is no lazy discovery on the transfer path.
    ///      What remains is the early-out (~2.5k), the ordinary update, and a
    ///      first-time holder's three cold SSTOREs plus the one-off
    ///      `totalSupply()` staticcall.
    ///
    ///      Undersizing this is SILENT and permanent: the try/catch swallows the
    ///      out-of-gas, the transfer succeeds, and that holder's share is never
    ///      recorded. `test_G1_shareSyncGasClearsTheMeasuredWorstCase` measures
    ///      the real worst case and asserts this constant clears it, so the
    ///      number is checked against the code rather than against a comment.
    uint256 private constant SHARE_SYNC_GAS = 120_000;

    // ----------------------------------------------------------- immutables --
    //
    // Per-DEPLOYMENT, not per-launch. See the contract note.

    // forge-lint: disable-start(screaming-snake-case-immutable)

    /// @notice The EIP-1167 target every launch's reward tracker is cloned from.
    /// @dev Created by the constructor, never passed in - change 3 in the contract
    ///      note. A contract-created address, so it is not a top-level deployment:
    ///      a verifier or a deploy script reads it from here.
    address public immutable trackerImpl;

    /// @notice The v4 PoolManager singleton - the venue, and the one address the
    ///         reward denominator must exclude.
    ///
    /// @dev 🔴 THE EXCLUSION IS UNAVOIDABLY BROADER THAN "THE POOL", AND THAT IS
    ///      THE ONE COST OF REWARDS ON v4. Under v3 the pool is a contract with
    ///      its own address and excluding it excludes exactly the pool's
    ///      inventory. Under v4 there is no pool contract: this ONE address holds
    ///      every pool's inventory on the chain AND every ERC-20-6909 claim
    ///      balance any user has chosen to leave inside the PoolManager. So
    ///      excluding it also excludes a real holder who holds a claim rather than
    ///      the token.
    ///
    ///      The behaviour is disclosed rather than worked around, and the
    ///      workaround is a holder's to take: REDEEM THE CLAIM INTO THE ORDINARY
    ///      TOKEN AND THE SHARE APPEARS. Redemption is an ERC-20 transfer out of
    ///      the PoolManager, so it runs {_update} and {ArgusV4RewardTracker6-setShare}
    ///      like any other receipt. Constructed and then restored in
    ///      `test_X1_aClaimHolderIsExcluded` / `test_X2_redemptionRestoresTheShare`,
    ///      and §4 of the report gives the measured cost.
    address public immutable poolManager;

    /// @notice The quote asset this implementation was built for: the Portal's
    ///         default, the one a launch uses unless it is admitted under another.
    /// @dev NOT what a launch pays rewards in - that is {quoteAsset}, per clone.
    ///      Kept for one reader: a Portal cross-checks it against its own default
    ///      at deploy, so a `tokenImpl` built for a different default is refused
    ///      before any launch. Nothing in this contract reads it after the
    ///      constructor.
    address public immutable defaultQuoteAsset;

    /// @notice Where a creator writes the reward config for their own next launch.
    /// @dev Read ONCE, during {initialize}, keyed by `owner` - which
    ///      the Portal's `_deployParts` sets to its own `msg.sender`, so the key is
    ///      the creator that signed the launch. See {ArgusV4LaunchConfig} for why the config cannot ride
    ///      the seam.
    ArgusV4LaunchConfig public immutable launchConfig;

    // forge-lint: disable-end(screaming-snake-case-immutable)

    // -------------------------------------------------------------- storage --

    string private _tokenName;
    string private _tokenSymbol;
    string private _logoURI;

    /// @notice The creator, as the Portal reported it.
    ///
    /// @dev 🔴 A LABEL, NOT A ROLE. Nothing in this contract is gated on it:
    ///      there is no `onlyOwner`, no `reduceTaxes` (there are no taxes), no
    ///      `renounce` (there is nothing to renounce) and no mint. It is stored
    ///      for two uses and no others - it is the key {_wireRewards} reads the
    ///      creator's config under, and it is what explorers and this pad's front
    ///      end display. `test_H3_ownerHasNoPowers` enumerates every
    ///      state-changing entry point and asserts none of them consults it after
    ///      {initialize}.
    address public owner;

    /// @notice The Portal that launched this token.
    address public portal;

    /// @notice The quote asset THIS launch was admitted under and paired
    ///         against, as the Portal passed it.
    /// @dev NOT NECESSARILY WHAT A `RewardMode.QUOTE` TRACKER PAYS IN, and that
    ///      is change 1. Under Portal #7 a non-keep quote's tracker pays USDC;
    ///      read the tracker's own `payoutAsset()` for the payout. This getter
    ///      keeps answering the pairing, which is what "paired against" means to
    ///      every reader that already calls it.
    ///
    ///      Per clone, written once by {initialize}, never zero on a clone.
    ///      `address(0)` on the IMPLEMENTATION, and that is deliberate: a Portal
    ///      that still reads `quoteAsset()` off the implementation for its
    ///      deploy-time check gets zero and refuses, loudly, rather than accepting
    ///      a token whose quote it has misread. Such a Portal must read
    ///      {defaultQuoteAsset}. NOTHING here assumes its decimals; see the
    ///      tracker's P-2.
    address public quoteAsset;

    /// @notice This launch's reward tracker, or `address(0)` under
    ///         `RewardMode.NONE`.
    address public rewardTracker;

    /// @notice The mode this launch was configured with.
    RewardMode public rewardMode;

    bool private _initialized;

    /// @notice Addresses whose balances are not counted as reward shares.
    /// @dev Mirrors what the tracker was initialized with. Fixed forever: there
    ///      is deliberately no setter, so an exemption can never be handed out or
    ///      revoked after launch. Same discipline as
    ///      `ArgusTaxToken`'s `isExempt`.
    mapping(address account => bool) public isExempt;

    // --------------------------------------------------------------- events --

    /// @dev Emitted instead of reverting when the tracker misbehaves. A revert
    ///      here would revert the transfer - and on the launch path, the launch.
    event ShareSyncFailed(address indexed user);

    event RewardTrackerCreated(address indexed tracker, RewardMode mode, address payoutAsset);

    // --------------------------------------------------------------- errors --

    /// @dev {initialize}'s tenth argument was neither the launch's quote nor
    ///      {defaultQuoteAsset}. Change 2 in the contract note.
    error PayoutAssetNotAllowed();

    // ---------------------------------------------------------- constructor --

    /// @dev Locks the implementation. A clone gets fresh storage and initializes
    ///      normally; the implementation can never be initialized, so nobody can
    ///      take ownership of the address every clone points at. `ArgusV4Portal`
    ///      depends on this - `_deployParts` clones and initializes in one
    ///      transaction precisely because an un-run `initialize` is claimable.
    constructor(address poolManager_, address defaultQuoteAsset_, ArgusV4LaunchConfig launchConfig_)
        ERC20("", "")
    {
        if (
            poolManager_ == address(0) || defaultQuoteAsset_ == address(0)
                || address(launchConfig_) == address(0)
        ) revert ArgusErrors.ZeroAddress();

        // Change 3. The tracker this token clones is the one it creates, so the
        // pairing is a fact of this bytecode rather than of a deploy argument.
        // Its own constructor locks it, exactly as this one locks this.
        trackerImpl = address(new ArgusV4RewardTracker6());
        poolManager = poolManager_;
        defaultQuoteAsset = defaultQuoteAsset_;
        launchConfig = launchConfig_;

        _initialized = true;
    }

    // ---------------------------------------------------------- initialize --

    /// @notice The seam.
    ///         `initialize(string,string,string,uint256,address,address,address,address[],address,address)`.
    ///
    /// @dev THE SIGNATURE IS FIXED BY {IArgusV4LaunchToken7}, which this contract
    ///      inherits, so a drift is a compile error. `test_S1` in
    ///      `ArgusV4LaunchToken7.t.sol` also asserts the literal, so changing the
    ///      interface and this function together is still a red test.
    ///
    ///      `quoteAsset_` is the ninth argument, as on #6: the asset the Portal
    ///      admitted this launch under and paired its pool against. Stored as
    ///      {quoteAsset} and read by nothing on the payout path. Zero is refused.
    ///
    ///      `payoutAsset_` is the tenth and the only new one: what a
    ///      `RewardMode.QUOTE` tracker pays holders in. It must be `quoteAsset_`
    ///      (a keep-listed quote, or the default) or {defaultQuoteAsset} (USDC,
    ///      for a quote that is converted). Anything else, zero included, is
    ///      {PayoutAssetNotAllowed}. Checked under every mode, so a Portal that
    ///      passes a wrong value fails on its first launch rather than on its
    ///      first QUOTE-mode launch.
    ///
    ///      The three strings are `memory` where the original's are `calldata`,
    ///      and that is the stack rather than a preference: nine arguments with
    ///      three calldata strings and a calldata array are one slot too deep for
    ///      the legacy code generator INSIDE THE ABI DECODER (`forge build`:
    ///      "Stack too deep ... dataEnd"), and `via_ir` is not this repository's
    ///      setting. A `memory` string is one stack slot, a `calldata` one is two.
    ///      The TENTH argument is paid for the same way: `extraExempt` moves to
    ///      `memory` as well, which is one more slot freed. Data location is not
    ///      part of the ABI, so the selector does not depend on it.
    ///
    ///      `extraExempt` carries the fee locker on a Portal launch, and the
    ///      Portal's note says why it is the one address a v4 launch must exempt:
    ///      "the locker receives the token side of the LP fees straight out of the
    ///      PoolManager, which a tax token would read as a buy"
    ///      (`ArgusV4Portal`'s note on {IArgusV4LaunchToken}). This token has no tax, so there is
    ///      no buy to misread - but the locker must still be out of the reward
    ///      denominator, because it is handed the token side of every fee harvest
    ///      and would otherwise accrue rewards on value it is about to burn. The
    ///      list is passed straight through to the tracker.
    function initialize(
        string memory name_,
        string memory symbol_,
        string memory logoURI_,
        uint256 totalSupply_,
        address supplyRecipient,
        address owner_,
        address portal_,
        address[] memory extraExempt,
        address quoteAsset_,
        address payoutAsset_
    ) external {
        if (_initialized) revert ArgusErrors.AlreadyInitialized();
        _initialized = true;

        if (
            portal_ == address(0) || supplyRecipient == address(0) || totalSupply_ == 0
                || quoteAsset_ == address(0)
        ) {
            revert ArgusErrors.ZeroAddress();
        }
        // Change 2. The two values Portal #7 can pass, and nothing else.
        if (payoutAsset_ != quoteAsset_ && payoutAsset_ != defaultQuoteAsset) revert PayoutAssetNotAllowed();

        _tokenName = name_;
        _tokenSymbol = symbol_;
        _logoURI = logoURI_;
        owner = owner_;
        portal = portal_;
        quoteAsset = quoteAsset_;

        // The exempt set, in one place, and it is the tracker's exclusion set
        // too. `address(this)` and the venue are here for the same reason they
        // are in the tracker; the caller-supplied entries are the locker.
        isExempt[address(this)] = true;
        isExempt[portal_] = true;
        isExempt[poolManager] = true;
        isExempt[ArgusConstants.DEAD] = true;
        isExempt[address(0)] = true;
        for (uint256 i; i < extraExempt.length; ++i) {
            if (extraExempt[i] != address(0)) isExempt[extraExempt[i]] = true;
        }

        // ONE list, written to the token's own set and handed to the tracker, so
        // the two sets are equal by construction. See the tracker's {initialize}.
        address[] memory exempt = new address[](extraExempt.length + 1);
        exempt[0] = portal_;
        for (uint256 i; i < extraExempt.length; ++i) {
            exempt[i + 1] = extraExempt[i];
        }

        _wireRewards(owner_, payoutAsset_, exempt);

        // R1. EXACTLY ONCE, EXACTLY THIS MUCH, AND NOWHERE ELSE IN THIS
        // CONTRACT. Last, so the tracker exists before the first balance moves
        // and the mint itself is a share update like any other.
        _mint(supplyRecipient, totalSupply_);
    }

    /// @dev Resolve the creator's config and clone a tracker if they asked for
    ///      one. Split from {initialize} for the stack, and because the whole of
    ///      "how does a frozen seam carry a per-launch flag" is one function.
    ///
    ///      A CONFIG READ MUST NOT BE ABLE TO FAIL A LAUNCH. The registry is
    ///      ownerless and has no failure mode of its own, but it is an external
    ///      call from inside the launch transaction, so it is wrapped: a registry
    ///      that somehow cannot answer yields `RewardMode.NONE` and the launch
    ///      proceeds without rewards. Losing rewards is recoverable by launching
    ///      again; a launch that reverts after the Portal has already deployed a
    ///      locker is not.
    function _wireRewards(address owner_, address payoutAsset_, address[] memory exempt) private {
        if (owner_ == address(0)) return;

        RewardMode m;
        uint96 minShare;
        try launchConfig.configFor(owner_) returns (RewardMode m_, uint96 s_) {
            m = m_;
            minShare = s_;
        } catch {
            return;
        }
        if (m == RewardMode.NONE) return;

        // THE WHOLE OF THE MODE, AND IT IS ONE TERNARY. See the tracker's P-1.
        // `payoutAsset_` is what Portal #7 decided holders are paid in - the
        // launch's quote when it is keep-listed, USDC when it is converted - and
        // NOT `quoteAsset_`: the one operand this copy exists to change.
        address payoutAsset = m == RewardMode.IN_KIND ? address(this) : payoutAsset_;

        address tracker = Clones.clone(trackerImpl);
        ArgusV4RewardTracker6(payable(tracker))
            .initialize(address(this), payoutAsset, poolManager, m, minShare, exempt);

        rewardTracker = tracker;
        rewardMode = m;

        // The tracker is a party to token transfers under `IN_KIND` and holds a
        // float it owes out, so it must never be a shareholder itself. It
        // excludes itself; this mirrors it on the token so the two sets agree.
        isExempt[tracker] = true;

        emit RewardTrackerCreated(tracker, m, payoutAsset);
    }

    // ------------------------------------------------------------- metadata --

    /// @dev ERC20's `_name`/`_symbol` are written by ITS constructor, which never
    ///      runs for a clone - a clone would report the implementation's empty
    ///      strings. These read our own storage instead.
    function name() public view override returns (string memory) {
        return _tokenName;
    }

    function symbol() public view override returns (string memory) {
        return _tokenSymbol;
    }

    /// @notice The token's artwork, as a URI.
    /// @dev THE NAME IS THE FEATURE, exactly as in `ArgusTaxToken`: `logo()` is
    ///      selector `0xfb7f21eb` and it is the first thing explorers, wallets and
    ///      this repository's own `tools/arc-tokens.mjs` staticcall for a token's
    ///      art. A token that only emits its image in a launch event is invisible
    ///      to all of them.
    function logo() external view returns (string memory) {
        return _logoURI;
    }

    // -------------------------------------------------------- transfer hook --

    /// @notice The ONLY override, and it takes nothing.
    ///
    /// @dev `V4_DESIGN_CONSTRAINTS.md` §7.3 item 8 asks what replaces the
    ///      dividend tracker's balance feed once the `_update` override is removed
    ///      to drop the tax. THIS IS THE ANSWER, AND IT IS THAT THE OVERRIDE
    ///      STAYS AND THE TAX GOES. The feed was never the tax's passenger; they
    ///      merely shared a function. What is left moves no value, takes no fee
    ///      and can refuse no transfer - it reports two post-transfer balances to
    ///      the tracker and returns.
    ///
    ///      Extends OpenZeppelin's {ERC20} DIRECTLY and that is load-bearing, for
    ///      the reason `ArgusTaxToken`'s header records: an earlier token in this
    ///      codebase inserted itself into a three-deep chain and its `_update`
    ///      override became a silent no-op, because `super._update` resolved to a
    ///      sibling base rather than to ERC20. Nothing reverted. One base, one
    ///      unambiguous `super`.
    ///
    ///      `super` FIRST, ALWAYS. The tracker settles against the POST-transfer
    ///      balance - see {ArgusV4RewardTracker6-setShare} - so reading before the
    ///      move would reprice the window that just closed. Mutating this order is
    ///      mutant M4 and it goes red.
    function _update(address from, address to, uint256 value) internal override {
        super._update(from, to, value);

        address tracker = rewardTracker;
        if (tracker == address(0)) return;

        // A mint has `from == 0` and a burn `to == 0`; neither is a holder and
        // both are excluded in the tracker anyway. Skipped here so the launch
        // mint does not pay for a call whose answer is known.
        if (from != address(0)) _trySetShare(tracker, from);
        if (to != address(0)) _trySetShare(tracker, to);
    }

    /// @dev Best-effort, gas-capped, never bubbling. A reverting or gas-hungry
    ///      tracker must not be able to brick every transfer of this token -
    ///      including the Portal's own curve mint, which would strand a launch
    ///      after the supply had already left.
    ///
    ///      THE COST OF SWALLOWING IS REAL AND IS NAMED RATHER THAN HIDDEN: a
    ///      swallowed failure means that holder's share is silently not recorded,
    ///      they earn nothing from then on, and `totalShares` is wrong. The event
    ///      is the only signal. {SHARE_SYNC_GAS} is sized against measured cost
    ///      for exactly this reason.
    function _trySetShare(address tracker, address user) private {
        try ArgusV4RewardTracker6(payable(tracker)).setShare{gas: SHARE_SYNC_GAS}(user, balanceOf(user)) {}
        catch {
            emit ShareSyncFailed(user);
        }
    }
}

src/libraries/ArgusUnits.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/// @title ArgusUnits
/// @notice The one place that knows Arc's native asset has two decimal scales.
///
/// Arc's gas token IS USDC, and it is reachable two ways that are the SAME
/// BALANCE, not two assets:
///
///   - natively, at **18 decimals** (`address(x).balance`, `msg.value`)
///   - through an ERC-20 view at `0x3600...0000`, at **6 decimals**
///
/// Verified on Arc mainnet against live addresses: for the STEVE/USDC pool,
/// `balance` was 31622011506000000000000 and `balanceOf` was 31622011506 -
/// exactly 1e12 apart. In a real swap every `0x3600` Transfer is mirrored by an
/// EIP-7708 native log at the same 1e12 ratio, so an ERC-20 `transfer` moves the
/// native balance and receiving `msg.value` credits `balanceOf`. There is no
/// wrap step, no `deposit()`, no `withdraw()`. (That is exactly why the Uniswap
/// SwapRouter02 on Arc points `WETH9()` at a 53-byte stub that reverts on every
/// call - nothing needs it.)
///
/// The asymmetry that bites: a **native** transfer can move any wei amount, but
/// the **ERC-20 view cannot represent anything below 1e12**. So every value that
/// crosses into an ERC-20 call (a swap, an approve) must be floored to a 1e12
/// multiple, with the remainder retained rather than assumed away. Rounding the
/// other way promises out more than the contract holds, which surfaces as the
/// final claimer reverting - the classic residual-carry bug.
///
/// Amounts carry their scale in the name everywhere in this codebase:
/// `...Native18` or `...Usdc6`. A wrong scale is otherwise invisible and will
/// pass a test that is wrong in the same direction.
library ArgusUnits {
    /// @dev Arc's ERC-20 view onto the native USDC balance. 6 decimals.
    address internal constant USDC = 0x3600000000000000000000000000000000000000;

    /// @dev 10 ** (18 - 6). Native wei per one ERC-20 unit.
    uint256 internal constant SCALE = 1e12;

    /// @notice Native (18dp) -> ERC-20 view (6dp), rounding DOWN.
    /// @dev Down is not a preference, it is the safe direction: the result is
    ///      about to be handed to a contract that will actually move it.
    function toUsdc6(uint256 amountNative18) internal pure returns (uint256) {
        return amountNative18 / SCALE;
    }

    /// @notice ERC-20 view (6dp) -> native (18dp). Always exact.
    function toNative18(uint256 amountUsdc6) internal pure returns (uint256) {
        return amountUsdc6 * SCALE;
    }

    /// @notice The largest 1e12 multiple at or below `amountNative18`, plus what
    ///         was left over.
    /// @dev Use before any swap or approve: send `spendableNative18`, keep
    ///      `dustNative18` on the books so it is neither double-counted nor lost.
    ///      It will be swept into a later swap-back once enough accumulates.
    function splitDust(uint256 amountNative18)
        internal
        pure
        returns (uint256 spendableNative18, uint256 dustNative18)
    {
        unchecked {
            dustNative18 = amountNative18 % SCALE;
            spendableNative18 = amountNative18 - dustNative18;
        }
    }

    /// @notice True when `amountNative18` survives a round-trip through the
    ///         6-decimal view without loss.
    function isRepresentable(uint256 amountNative18) internal pure returns (bool) {
        return amountNative18 % SCALE == 0;
    }
}

src/ArgusV4RewardTracker6.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {ArgusConstants, ArgusErrors} from "./types/ArgusTypes.sol";
import {ArgusUnits} from "./libraries/ArgusUnits.sol";
import {RewardMode} from "./ArgusV4LaunchConfig.sol";

/// @notice The metadata read this tracker makes on its payout asset, once.
/// @dev Declared here rather than imported from OZ's `IERC20Metadata` because
///      only one function of it is called and a token whose `decimals()` reverts
///      must be refused rather than defaulted - see {ArgusV4RewardTracker6-initialize}.
interface IERC20Decimals {
    function decimals() external view returns (uint8);
}

/// @title ArgusV4RewardTracker6
/// @notice Pro-rata holder rewards for ONE `ArgusV4LaunchToken6`, in either the
///         launch's own quote asset or the token itself. Portal #6's tracker.
///
/// @dev {ArgusV4RewardTracker} WITH ONE CHANGE, AND THE CHANGE IS {receive}.
///      That contract is Portal #5's deployed `rewardTrackerImpl` and is not
///      edited; this is a copy (SPEC_PORTAL6.md §2.5). Everything below is its
///      text, carried over, except where a sentence named the paired token or
///      assumed the quote is Arc USDC.
///
///      WHY A COPY WAS NEEDED AT ALL. The original's {receive} accepted native
///      whenever `mode == RewardMode.QUOTE`, which read QUOTE as "native" - true
///      while every launch was paired against `0x3600`, whose ERC-20 view IS the
///      native balance. Portal #6 admits other quote assets per launch, and
///      {ArgusV4LaunchToken6} hands a QUOTE tracker that launch's own quote.
///      Under such a quote, native sent here raises a balance {syncDeposit} never
///      reads and {_transfer} never moves, on a contract with no owner and no
///      sweep. So the guard now asks the question it always meant: is the payout
///      asset the one the native balance mirrors? The five departures below are
///      unchanged, and this is NOT a sixth: they are departures from the v3
///      {ArgusDividendTracker}, and this is a change from the v4 original.
///
///      THE TESTS AND TOOLS NAMED BELOW RUN AGAINST THE ORIGINAL. Every `test_*`,
///      `AuditP4` case and `ordering-census.mjs` rule cited in this file was
///      written against {ArgusV4RewardTracker} and still executes against it. They
///      describe this code because it is that code outside {receive}; they do not
///      execute it. What executes against THIS contract is
///      `test/unit/ArgusV4LaunchToken6.t.sol`.
///
///      PORTED FROM {ArgusDividendTracker}, WHICH IS LIVE AND AUDITED, WITH FIVE
///      DELIBERATE DEPARTURES. Each is a place the v3 contract cannot be copied
///      verbatim without being wrong on a v4 venue, and each is named so a
///      reviewer can check the list against the code instead of diffing 900
///      lines.
///
///      THE COUNT WAS FOUR AND THE CODE ALWAYS HAD FIVE. P-5 is declared forty
///      lines below the block that holds P-1..P-4, on {PAYOUT_GAS_STIPEND}'s
///      absence, and cross-referenced three more times. A reviewer who trusted
///      the number stopped at P-4 and never reached the departure that DELETED
///      A GUARD. Pinned by `test_R1_theDeparturesAreFiveAndTheHeaderSaysFive`,
///      which counts `P-N` declarations in this file and fails if the header's
///      number and the code's disagree - in either direction.
///
///      ------------------------------------------------------------------
///      P-1  THE PAYOUT IS AN ERC-20 TRANSFER, NEVER A NATIVE SEND, AND THAT
///           IS WHAT MAKES ONE FLAG ENOUGH.
///      ------------------------------------------------------------------
///      {ArgusDividendTracker} pays with `to.call{value:}` at every one of its
///      exits, so its payout asset is native and cannot be anything else - which
///      is why an in-kind mode is not expressible in it at all rather than
///      merely absent. Here {payoutAsset} is ONE STORED ADDRESS and every exit
///      goes through {_pay}. `RewardMode.QUOTE` stores the quote asset;
///      `RewardMode.IN_KIND` stores the launched token. Nothing else in this
///      contract branches on the mode, which is what "one flag, not two code
///      paths" means concretely.
///
///      When the quote is Arc USDC this is not a portability nicety, it is free:
///      `0x3600`'s ERC-20 `transfer` MOVES THE NATIVE BALANCE (see {ArgusUnits}),
///      so an ERC-20 transfer of the quote asset and a native send are the same
///      movement. Under any other quote the ERC-20 form is the ONLY movement,
///      which is why {receive} refuses native there. The ERC-20 form is also the
///      one that works when the payout asset is the launched token.
///
///      ------------------------------------------------------------------
///      P-2  NO DECIMALS CONSTANT ANYWHERE ON THE REWARD PATH.
///      ------------------------------------------------------------------
///      The accumulator, `pending`, the bank and every event are denominated in
///      the PAYOUT ASSET'S OWN UNITS. There is no `1e12`, no `SCALE`, no
///      `toNative18` and no 18-decimal assumption in this file, so the contract
///      is decimals-agnostic BY CONSTRUCTION rather than by parameterisation -
///      which is the stronger property, because a parameter can be threaded
///      wrongly and an absent constant cannot.
///      {ArgusDividendTracker} could not do this: its amounts are native 18dp by
///      necessity and its own natspec says so.
///      `decimals()` IS still read once, at {initialize}, and recorded - not to
///      scale anything, but so a payout asset that cannot answer is refused at
///      launch instead of surfacing later, and so an indexer can read the scale
///      of the numbers in the events off the contract.
///      Pinned by `test_D1_quoteDecimalsAreNotAssumed`, which runs the identical
///      distribution against a 6-decimal and an 18-decimal payout asset and
///      asserts each holder is paid in that asset's own units. A hardcoded 1e12
///      anywhere on this path fails one of the two halves by a factor of 1e12.
///
///      ------------------------------------------------------------------
///      P-3  THE EXCLUDED VENUE IS KNOWN AT INITIALIZE. THERE IS NO LAZY
///           DISCOVERY AND NOTHING ON THE TRANSFER PATH TO DISCOVER.
///      ------------------------------------------------------------------
///      {ArgusDividendTracker-_syncPool} staticcalls `token.mainPool()` on every
///      {setShare} until a pool exists, because on v3 the pool address is not
///      known when the tracker is initialized. On v4 the venue is the
///      PoolManager SINGLETON - one address, the same for every launch on the
///      chain, known before any of these contracts are deployed - so it is
///      passed in and excluded here, once. That deletes the staticcall from the
///      hot path and with it the ~113k one-time share update
///      {ArgusTaxToken-SHARE_SYNC_GAS} had to be sized to survive.
///
///      🔴 AND IT IS THE HALF OF THE v4 SINGLETON THAT HELPS. The v3 shape
///      excludes exactly ONE pool, so a rival v3 pool at another fee tier is
///      permanently a shareholder that never claims and permanently dilutes
///      everyone who does. Under v4 every pool on the chain - the launch pool, a
///      rival at another tier, one with a hook - holds its inventory inside this
///      one excluded address, so that entire class is structurally unreachable.
///      The RESIDUAL, stated because it is not zero: a v3 pool for this token on
///      the same chain is a different contract at its own address and WOULD be
///      an unexcluded shareholder. There is no setter to add it and there will
///      not be one; see {isExcluded}.
///
///      ------------------------------------------------------------------
///      P-4  `strandedSince` IS CLEARED AFTER A PAYOUT SUCCEEDS, AND ONLY THEN.
///      ------------------------------------------------------------------
///      `ARC_V4_NOTES.md` §4 blocked this port on a finding against the v3
///      tracker: `strandedSince` was written only inside `reclaimStranded` and
///      cleared only inside its success branch, so a holder that failed one
///      probe and was then paid in full by any other route kept a live marker
///      and lost its whole {STRANDED_GRACE} window.
///
///      🔴 THIS SENTENCE USED TO CITE TWO LINE NUMBERS IN
///      `ArgusDividendTracker.sol` AND SAY THAT CONTRACT "STILL CARRIES THE
///      DEFECT". BOTH HALVES ARE NOW FALSE. `iRedFox/ArgusPad#6` (merge `9e803d8`) remediated that contract
///      and moved the lines. NO LINE NUMBER INTO THAT FILE IS CITED HERE ANY
///      MORE, deliberately: this file does not own it, a merge silently takes
///      its version, and a citation into a file you do not own is a claim with
///      an expiry date nobody is watching. The property, which is checkable
///      without a line number: `ArgusDividendTracker._clearStranded` is now
///      called from FIVE sites covering `claim`, `claimTo`, `_withdrawFor` and
///      `reclaimStranded`.
///
///      THE STATEMENT THIS FILE MAKES ABOUT ITSELF, AND WHAT ENFORCES IT.
///      The clear is ordered AFTER the external send in every one of the four
///      paths that can perform one, so a payout that moves nothing writes
///      nothing. That is stronger than "cleared on every successful payout",
///      and it is the half the original wording did not promise: the original
///      was satisfied by clearing BEFORE a send that does not revert, which is
///      what {_payOrPark} did, and it silently erased the marker on a failure.
///
///      Two enforcement layers, both of which have been shown to fail on the
///      defective code and pass on this one:
///        - BEHAVIOURAL: `AuditP4.test_A1`/`test_A2`/`test_A4`/`test_A6`, with
///          `test_A3` as the in-run control. All four go red when the clear is
///          moved back before the send.
///        - MECHANICAL: `tools/remediate-v4-token/ordering-census.mjs`, which
///          decides from the AST whether each clear precedes or follows its
///          send and whether every field committed before a non-reverting send
///          is restored on the failure path. It is proven by
///          `prove-ordering-census.mjs` on seven cases, including the real
///          pre-remediation v3 tracker.
///      Neither is a comment. `make census` runs the second one.
contract ArgusV4RewardTracker6 is ReentrancyGuard {
    /// @notice Largest batch {distribute} will attempt.
    /// @dev A ceiling, not a target - same reasoning as
    ///      {ArgusDividendTracker-MAX_BATCH}. Size real batches on measured gas.
    uint256 public constant MAX_BATCH = 200;

    /// @notice Ceiling on the dust filter's EFFECT, as a share of total supply.
    /// @dev Verbatim in intent from {ArgusDividendTracker-MAX_MINIMUM_SHARE_BPS}:
    ///      `minimumShareBalance` is creator-chosen, and unbounded it is a funnel
    ///      rather than a filter. Bounded at USE time because at {initialize} the
    ///      token has not minted yet and there is no supply to take a fraction of.
    uint16 public constant MAX_MINIMUM_SHARE_BPS = 10; // 0.1%

    /// @notice Aggregate eligible share that releases a banked deposit.
    uint16 public constant HELD_FLUSH_MIN_SHARE_BPS = 10; // 0.1%

    /// @notice How long a banked deposit may wait on the floor above.
    /// @dev SECONDS. Arc produces a block roughly every 0.506s, so a block count
    ///      carried from another chain means something very different here.
    uint256 public constant HELD_FLUSH_MAX_WAIT = 7 days;

    /// @notice How long a holder must be demonstrably unpayable before
    ///         {reclaimStranded} may fold its rewards back to everyone else.
    uint256 public constant STRANDED_GRACE = 30 days;

    /// @notice 🔴 THERE IS NO PAYOUT GAS STIPEND, AND ITS ABSENCE IS A MEASURED
    ///         DECISION RATHER THAN AN OMISSION. THIS IS P-5.
    ///
    /// @dev {ArgusDividendTracker} caps every batched payout at
    ///      {ArgusConstants-PAYOUT_GAS_STIPEND} and gives a long, correct reason:
    ///      its payout is `to.call{value:}`, which runs the RECIPIENT'S code, so
    ///      one hostile `receive()` can eat 63/64 of a keeper's transaction and a
    ///      recipient reverting with ~96KB of return data can make a 200-holder
    ///      batch unmineable.
    ///
    ///      NONE OF THAT CLASS EXISTS HERE, because of P-1. An ERC-20 `transfer`
    ///      CALLS NO RECIPIENT HOOK - there is no `receive()`, no fallback, no
    ///      `onTokenReceived` on this path - so a recipient cannot spend the
    ///      caller's gas, cannot return data, and cannot refuse. The only code a
    ///      payout runs is the PAYOUT ASSET'S, and that address is fixed at
    ///      {initialize} and is either the quote asset or this launch's own token.
    ///      It is never attacker-chosen.
    ///      `test_P8_anErc20PayoutRunsNoRecipientCode` is the measurement: a
    ///      recipient contract whose every entry point reverts is paid
    ///      successfully.
    ///
    ///      A stipend was written first and then DELETED, for the reason
    ///      `ArgusV4Portal`'s D-5 gives about its own quote-side ceiling - a guard
    ///      that can refuse nothing is not depth, it is furniture. Keeping it was
    ///      also actively harmful: at 60,000 it was BELOW the cost of an in-kind
    ///      payout, which transfers this token and therefore runs two
    ///      {ArgusV4LaunchToken6-SHARE_SYNC_GAS}-bounded share updates, so every
    ///      batched `IN_KIND` payout would have failed and parked. Found by
    ///      `test_K8_distributeWorksInKind` going red, not by review.
    ///
    ///      WHAT IS GIVEN UP, STATED PLAINLY: a per-holder gas bound inside
    ///      {distribute}. So the batch's cost is linear in its size and in the
    ///      payout asset's own cost, and {MAX_BATCH} is a ceiling rather than a
    ///      safe default - measured per-holder costs for both modes are in §6 of
    ///      the report. A keeper sizes batches on those numbers.

    // -------------------------------------------------------------- storage --

    /// @notice The launch token. The only address allowed to move shares.
    address public token;

    /// @notice What holders are paid in. The whole of {RewardMode}, resolved to
    ///         an address at {initialize}. See P-1.
    address public payoutAsset;

    /// @notice The mode this launch was configured with. Stored for disclosure -
    ///         nothing in this contract reads it after {initialize}.
    RewardMode public mode;

    /// @notice `payoutAsset.decimals()`, read once. Recorded, never used to
    ///         scale. See P-2.
    uint8 public payoutDecimals;

    /// @notice The v4 PoolManager. Excluded at {initialize}; see P-3.
    address public venue;

    uint96 public minimumShareBalance;

    bool private _initialized;

    /// @notice When {heldPayout} first became non-zero. Drives {HELD_FLUSH_MAX_WAIT}.
    uint64 public heldSince;

    /// @notice The token's total supply, cached on first successful read.
    /// @dev Lazy for the reason {ArgusDividendTracker-totalSupplyCache} is: the
    ///      token has not minted when this contract is initialized. Safe to
    ///      cache because {ArgusV4LaunchToken6} mints exactly once and has no
    ///      burn and no mint entry point - a property of THAT contract, asserted
    ///      by `test_T3_supplyIsFixedForever`, not an assumption about tokens in
    ///      general.
    uint256 public totalSupplyCache;

    uint256 public accPerShareX128;
    uint256 public totalShares;

    /// @notice Deposits that arrived with nobody eligible to receive them.
    uint256 public heldPayout;

    /// @notice What this contract believes it has been given and still owes out.
    /// @dev THE REASON A PULL-ONLY DEPOSIT IS NOT ENOUGH ON ARC. When the payout
    ///      asset is Arc USDC it is an ERC-20 VIEW onto the native balance, so a
    ///      plain native send to this address raises `payoutAsset.balanceOf(this)`
    ///      with NO ERC-20 call
    ///      to observe - a `deposit()` that only ever pulls could never see value
    ///      forwarded that way, and value nobody can see is value nobody can be
    ///      paid. {syncDeposit} closes it by accounting the difference between
    ///      the real balance and this figure.
    uint256 public accountedBalance;

    uint256 public totalDeposited;
    uint256 public totalPaid;

    /// @notice Settled-but-unpaid rewards. Also where a failed payout lands.
    mapping(address => uint256) public pending;

    /// @notice When {reclaimStranded} first proved `user` unpayable at full gas.
    /// @dev Cleared by {_clearStranded} AFTER a send that actually succeeded, on
    ///      every path that can send - see P-4. The ordering is the claim, not
    ///      merely the presence of a clear: a clear placed before a send that
    ///      parks on failure erases this marker on a payout that moved nothing,
    ///      and that is what shipped. Enforced by `AuditP4` and by
    ///      `ordering-census.mjs` RULE 1; NOT enforced by any set-equality scan,
    ///      which is green in both directions.
    mapping(address => uint64) public strandedSince;

    mapping(address => uint256) private _share;
    mapping(address => uint256) private _debtX128;
    mapping(address => bool) private _excluded;

    // --------------------------------------------------------------- events --

    event ShareUpdated(address indexed user, uint256 oldShare, uint256 newShare);
    event Deposited(uint256 amount, uint256 accPerShareX128);
    event DepositHeld(uint256 amount, uint256 totalHeld);
    event DepositHeldReleased(uint256 amount, uint256 totalShares);
    event Paid(address indexed user, address indexed destination, uint256 amount);
    event PayFailed(address indexed user, uint256 amount);
    event Excluded(address indexed account);
    event StrandedProbed(address indexed user, uint256 amount, uint256 redistributableAt);
    event StrandedRedistributed(address indexed user, uint256 amount, uint256 totalShares);

    // --------------------------------------------------------------- errors --

    error BatchTooLarge();
    error NothingToClaim();
    error BankNotReleasable();
    error NotAContract();
    error PayoutFailed();
    error NothingDeposited();
    /// @dev The payout asset does not answer `decimals()`, or answers with more
    ///      than 18. Refused at launch rather than tolerated: an asset whose
    ///      scale cannot be read is one whose event stream cannot be interpreted.
    error PayoutAssetUnreadable();

    /// @dev A tracker was initialized with `RewardMode.NONE`. Not a
    ///      configuration this contract can express: `NONE` means the token
    ///      clones no tracker at all, so reaching {initialize} with it is a wiring
    ///      bug in the caller rather than a creator's choice.
    error RewardsDisabled();

    /// @dev A native send reached a tracker whose payout asset is not native.
    ///      See {receive}.
    error NativeNotThePayoutAsset();

    // ------------------------------------------------------------ lifecycle --

    /// @dev Locks the implementation. A clone gets fresh storage and initializes
    ///      normally; the implementation can never be initialized, so nobody can
    ///      claim the address every clone points at. This is
    ///      {ArgusDividendTracker}'s audit finding L-4 taken as a starting
    ///      condition rather than as a fix.
    constructor() {
        _initialized = true;
    }

    /// @param token_ the launch token; the only address that may move shares
    /// @param payoutAsset_ what holders are paid in - the launch's own quote asset
    ///        in `RewardMode.QUOTE`, `token_` itself in `RewardMode.IN_KIND`
    /// @param venue_ the v4 PoolManager singleton. Excluded here; see P-3.
    /// @param exempt addresses the launch needs excluded that this contract cannot
    ///        work out for itself. {ArgusV4LaunchToken6} passes the PORTAL plus
    ///        whatever the Portal's own `extraExempt` carried - on a real launch
    ///        that is the fee locker, which is paid the token side of the LP fees
    ///        straight out of the PoolManager and must not be a shareholder.
    ///        The token passes the SAME list it writes into its own `isExempt`, so
    ///        the two sets are equal by construction rather than by agreement;
    ///        `test_E4_theTwoExclusionSetsAgree` pins it.
    function initialize(
        address token_,
        address payoutAsset_,
        address venue_,
        RewardMode mode_,
        uint96 minimumShareBalance_,
        address[] calldata exempt
    ) external {
        if (_initialized) revert ArgusErrors.AlreadyInitialized();
        if (token_ == address(0) || payoutAsset_ == address(0) || venue_ == address(0)) {
            revert ArgusErrors.ZeroAddress();
        }
        if (mode_ == RewardMode.NONE) revert RewardsDisabled();
        _initialized = true;

        token = token_;
        payoutAsset = payoutAsset_;
        venue = venue_;
        mode = mode_;
        minimumShareBalance = minimumShareBalance_;

        // READ, RECORDED, NEVER USED TO SCALE. See P-2. A `try` rather than a
        // bare call because a payout asset that cannot answer must fail the
        // launch here, loudly, and not later inside a distribution.
        try IERC20Decimals(payoutAsset_).decimals() returns (uint8 d) {
            if (d > 18) revert PayoutAssetUnreadable();
            payoutDecimals = d;
        } catch {
            revert PayoutAssetUnreadable();
        }

        _excluded[address(this)] = true;
        _excluded[token_] = true;
        _excluded[venue_] = true;
        _excluded[ArgusConstants.DEAD] = true;
        _excluded[address(0)] = true;
        for (uint256 i; i < exempt.length; ++i) {
            if (exempt[i] != address(0)) _excluded[exempt[i]] = true;
        }
    }

    // ----------------------------------------------------------- share hooks --

    /// @notice Record `user`'s post-transfer balance as its share.
    ///
    /// @dev Settles against this contract's OWN stored share, never the `balance`
    ///      argument - {ArgusDividendTracker}'s departure 1, for the same reason:
    ///      `balance` is the POST-transfer figure and settling against it would
    ///      reprice the window that just closed.
    ///
    ///      🔴 THIS FUNCTION IS REACHED REENTRANTLY IN `IN_KIND` MODE AND THAT IS
    ///      THE MOST DANGEROUS THING IN THIS FILE. An in-kind payout is a
    ///      transfer of the launched token, so {_payOrPark} calls the token, the
    ///      token calls back here, and this runs INSIDE the payout.
    ///
    ///      WHAT ACTUALLY MAKES IT SAFE IS THE `_settle` AT THE TOP OF
    ///      {_payOrPark}, NOT THE ORDER OF THE LINES AFTER IT - and an earlier
    ///      version of this comment said the opposite. That settle advances
    ///      `_debtX128[user]` to `accPerShareX128`, so when the reentrant call
    ///      arrives {_settle} returns on its FIRST line and there is nothing to
    ///      double-credit no matter where `pending` was zeroed.
    ///      MEASURED, and it is why the claim was rewritten: mutant
    ///      `R1-pending-zeroed-after-the-transfer` moves the zeroing to AFTER the
    ///      transfer and SURVIVES the whole suite. Zeroing first is real depth -
    ///      it is what would still hold if the settle were ever removed - but it
    ///      is not the thing doing the work today, and a single-line mutation
    ///      cannot see through the two. The COMPOUND
    ///      `R1b-compound-no-settle-and-pending-zeroed-late` removes both and is
    ///      the mutant that measures the stack, exactly as
    ///      `ArgusV4Portal`'s D-5 uses M20 against its own four layers.
    ///      `test_K5_inKindPayoutCannotDoubleCredit` drives the live path and
    ///      asserts the conservation law the reentrancy would break.
    ///
    ///      This is deliberately NOT solved with a reentrancy guard: blocking the
    ///      callback would make the token's own `_update` revert and take the
    ///      payout with it.
    function setShare(address user, uint256 balance) external {
        if (msg.sender != token) revert ArgusErrors.OnlyToken();

        uint256 newShare = (_excluded[user] || balance < _effectiveMinShare()) ? 0 : balance;
        uint256 oldShare = _share[user];

        // Nothing to do, and nothing lost by skipping the settle: accrual is
        // linear in a share that did not change.
        if (newShare == oldShare) return;

        _settle(user);

        _share[user] = newShare;
        totalShares = totalShares - oldShare + newShare;

        emit ShareUpdated(user, oldShare, newShare);
    }

    /// @notice The dust filter actually in force: the configured value, capped at
    ///         {MAX_MINIMUM_SHARE_BPS} of total supply.
    /// @dev Fails toward INCLUSION - an unreadable supply drops the filter rather
    ///      than applying it unbounded, so an unreadable supply can never be the
    ///      thing that concentrates rewards.
    function _effectiveMinShare() internal returns (uint256) {
        uint256 configured = minimumShareBalance;
        if (configured == 0) return 0;

        uint256 supply = _supply();
        if (supply == 0) return 0;

        uint256 cap = (supply * MAX_MINIMUM_SHARE_BPS) / ArgusConstants.BPS;
        return configured > cap ? cap : configured;
    }

    function _supply() internal returns (uint256) {
        uint256 cached = totalSupplyCache;
        if (cached != 0) return cached;

        (bool ok, bytes memory ret) = token.staticcall(abi.encodeWithSelector(IERC20.totalSupply.selector));
        if (!ok || ret.length < 32) return 0;

        uint256 supply = abi.decode(ret, (uint256));
        if (supply != 0) totalSupplyCache = supply;
        return supply;
    }

    /// @dev Removes an address from the denominator for good. Settles first: a
    ///      reward it earned while eligible is genuinely its own and stays
    ///      claimable.
    function _exclude(address account) internal {
        if (_excluded[account]) return;
        _excluded[account] = true;
        emit Excluded(account);

        uint256 oldShare = _share[account];
        if (oldShare == 0) return;

        _settle(account);
        _share[account] = 0;
        totalShares -= oldShare;

        emit ShareUpdated(account, oldShare, 0);
    }

    function _settle(address account) internal {
        uint256 perShare = accPerShareX128;
        uint256 debt = _debtX128[account];
        if (debt == perShare) return;

        _debtX128[account] = perShare;

        uint256 shares = _share[account];
        if (shares == 0) return;

        pending[account] += (shares * (perShare - debt)) >> 128;
    }

    // -------------------------------------------------------------- deposits --

    /// @notice Pull `amount` of the payout asset from the caller and distribute it.
    function deposit(uint256 amount) external nonReentrant {
        if (amount == 0) revert NothingDeposited();
        address asset = payoutAsset;

        uint256 before = IERC20(asset).balanceOf(address(this));
        // `transferFrom`, not `safeTransferFrom`: the received amount is measured
        // rather than assumed, so a fee-on-transfer payout asset is accounted at
        // what actually arrived instead of at what was asked for.
        (bool ok, bytes memory ret) = asset.call(
            abi.encodeWithSelector(IERC20.transferFrom.selector, msg.sender, address(this), amount)
        );
        if (!ok || (ret.length != 0 && !abi.decode(ret, (bool)))) revert PayoutFailed();

        uint256 received = IERC20(asset).balanceOf(address(this)) - before;
        if (received == 0) revert NothingDeposited();

        accountedBalance += received;
        _deposit(received);
    }

    /// @notice Distribute any balance this contract holds but has not yet
    ///         accounted for.
    /// @dev Permissionless and idempotent. MANDATORY on Arc rather than
    ///      convenient - see {accountedBalance}.
    function syncDeposit() external nonReentrant returns (uint256 amount) {
        uint256 real = IERC20(payoutAsset).balanceOf(address(this));
        uint256 known = accountedBalance;
        if (real <= known) revert NothingDeposited();

        amount = real - known;
        accountedBalance = real;
        _deposit(amount);
    }

    /// @notice Whether the banked balance may be released to current holders.
    /// @dev Two ways to qualify, and the second exists so the first can never be
    ///      a permanent lock. Identical rule for both callers, deliberately - an
    ///      on-demand exit under a weaker rule would be a second rule.
    function _bankReleasable(uint256 currentShares) internal returns (bool) {
        uint64 since = heldSince;
        if (since != 0 && block.timestamp >= uint256(since) + HELD_FLUSH_MAX_WAIT) return true;

        uint256 supply = _supply();
        if (supply == 0) return true;

        return currentShares >= (supply * HELD_FLUSH_MIN_SHARE_BPS) / ArgusConstants.BPS;
    }

    function _deposit(uint256 amount) internal {
        if (amount == 0) return;
        totalDeposited += amount;

        uint256 shares = totalShares;

        if (shares == 0) {
            // Nobody eligible holds anything. Do NOT advance the checkpoint:
            // dividing by a supply that does not exist burns the deposit instead
            // of banking it for whoever holds next.
            if (heldPayout == 0) heldSince = uint64(block.timestamp);
            heldPayout += amount;
            emit DepositHeld(amount, heldPayout);
            emit Deposited(amount, accPerShareX128);
            return;
        }

        uint256 total = amount;
        uint256 bank = heldPayout;
        if (bank != 0 && _bankReleasable(shares)) {
            total += bank;
            heldPayout = 0;
            heldSince = 0;
            emit DepositHeldReleased(bank, shares);
        }

        // The division truncates and the lost wei STAYS here rather than being
        // carried forward. Carrying it is the residual-carry bug
        // {ArgusDividendTracker-_deposit} documents: a holder settles many
        // deposits at once and one floor over the summed growth recovers wei that
        // each per-deposit floor had given away, so both sides claim it and the
        // shortfall surfaces as the last claimer's payout failing.
        accPerShareX128 += (total << 128) / shares;

        emit Deposited(total, accPerShareX128);
    }

    /// @notice Release a banked deposit on demand, with no further deposit needed.
    function flushBank() external nonReentrant returns (uint256 released) {
        uint256 bank = heldPayout;
        uint256 shares = totalShares;
        if (bank == 0 || shares == 0 || !_bankReleasable(shares)) revert BankNotReleasable();

        heldPayout = 0;
        heldSince = 0;
        accPerShareX128 += (bank << 128) / shares;

        emit DepositHeldReleased(bank, shares);
        emit Deposited(bank, accPerShareX128);
        return bank;
    }

    // --------------------------------------------------------------- payouts --

    function withdrawableOf(address user) public view returns (uint256) {
        uint256 shares = _share[user];
        uint256 accrued = shares == 0 ? 0 : (shares * (accPerShareX128 - _debtX128[user])) >> 128;
        return pending[user] + accrued;
    }

    /// @notice Pay the caller. Parks on failure rather than reverting.
    function withdraw() external nonReentrant returns (uint256) {
        return _payOrPark(msg.sender, msg.sender);
    }

    /// @notice Pay `user`. The keeper path, and identical to {withdraw} - see P-5
    ///         for why there is no capped variant.
    function withdrawFor(address user) external nonReentrant returns (uint256) {
        return _payOrPark(user, user);
    }

    /// @notice Pay the caller, forwarding all gas, and REVERT if it fails.
    /// @dev The single-address escape hatch for a holder the batch path cannot
