// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/// @title IArgusV4LaunchToken7
/// @notice The launch-token seam Portal #7 calls: {IArgusV4LaunchToken6}'s nine
///         arguments plus a TENTH, the asset a `RewardMode.QUOTE` tracker pays in.
///
/// @dev `initialize(string,string,string,uint256,address,address,address,address[],address,address)`
///      = `0x83c139e5`, pinned by literal in `test/unit/ArgusV4LaunchToken7.t.sol`.
///
///      WHY A SEPARATE ARGUMENT RATHER THAN A DIFFERENT NINTH ONE. Portal #7 pays
///      QUOTE-mode dividends in USDC when the launch's quote is not keep-listed
///      (SPEC_QUOTE_AUTO_ADMISSION.md §5b). Passing USDC as Token6's ninth argument
///      would do that with no new token code, and would make `quoteAsset()` answer
///      USDC on a pool paired against something else. Partners' indexers read that
///      getter. So the pairing and the payout are two arguments, and `quoteAsset()`
///      keeps meaning "paired against" (option ii in qa-11 §2.3, the owner's ruling).
///
///      A DIFFERENT SELECTOR FROM #6's, AND THE BREAK IS THE LOUD KIND. Portal #6
///      calling its nine-argument form against this token reverts inside
///      `_deployParts`, because the token has no fallback.
///
///      The array and all three strings are `memory`, not `calldata`, for the
///      implementation's stack; see {ArgusV4LaunchToken7-initialize}. Data
///      location is not part of the ABI, so neither the selector nor a caller
///      changes.
interface IArgusV4LaunchToken7 {
    function initialize(
        string memory name,
        string memory symbol,
        string memory logoURI,
        uint256 totalSupply,
        address supplyRecipient,
        address owner,
        address portal,
        address[] memory extraExempt,
        address quoteAsset,
        address payoutAsset
    ) external;
}

